#!/usr/bin/env python3
# Original reimplementation of a Lua 5.5-style interpreter, written from
# behavioural observation of the reference program.
import sys, os, math, time, random, struct, re
sys.setrecursionlimit(1000000)
try:
    import threading
    threading.stack_size(512*1024*1024)
except Exception:
    pass

LUA_VERSION = "Lua 5.5"
LUA_RELEASE = "Lua 5.5.1"
LUA_COPYRIGHT = "Lua 5.5.1  Copyright (C) 1994-2026 Lua.org, PUC-Rio"
INT_MIN = -(1<<63)
INT_MAX = (1<<63)-1
MASK64 = (1<<64)-1

def wrap_int(n):
    n &= MASK64
    if n > INT_MAX:
        n -= (1<<64)
    return n

def is_bool(v): return isinstance(v, bool)
def is_int(v): return isinstance(v, int) and not isinstance(v, bool)
def is_float(v): return isinstance(v, float)
def is_num(v): return is_int(v) or is_float(v)
def is_str(v): return isinstance(v, bytes)
def typename(v):
    if v is None: return "nil"
    if isinstance(v, bool): return "boolean"
    if is_int(v): return "number"
    if is_float(v): return "number"
    if isinstance(v, bytes): return "string"
    if isinstance(v, LuaTable): return "table"
    if isinstance(v, (LuaFunction, BuiltinFunction)): return "function"
    if isinstance(v, LuaThread): return "thread"
    if isinstance(v, UserData): return "userdata"
    return "userdata"

class LuaError(Exception):
    def __init__(self, value, traceback_text=None, already_prefixed=False):
        super().__init__(str(value))
        self.value = value
        self.traceback_text = traceback_text
        self.already_prefixed = already_prefixed

class SyntaxErr(Exception):
    def __init__(self, msg, source=None, line=None):
        self.msg = msg; self.source = source; self.line = line
        super().__init__(msg)
    def full(self):
        if self.source is not None:
            return "%s:%s: %s" % (self.source, self.line if self.line is not None else 1, self.msg)
        return self.msg

class Cell:
    __slots__=('value',)
    def __init__(self, value=None): self.value=value
    def __repr__(self): return f"Cell({self.value!r})"

def canon_key(v, for_set=False):
    if v is None:
        if for_set: raise KeyError("nil")
        return None
    if isinstance(v, bool): return ('b', v)
    if is_int(v): return ('n', v)
    if is_float(v):
        if math.isnan(v):
            if for_set: return ('nan',)
            return ('f', v)
        if v == int(v) and INT_MIN <= v <= INT_MAX:
            return ('n', int(v))
        return ('f', v)
    if isinstance(v, bytes): return ('s', v)
    return ('o', v)

def key_to_lua(ck):
    if ck is None: return None
    t=v=ck[0],ck[1]
    # handled below
    return ck[1]

class LuaTable:
    __slots__=('map','metatable','id')
    _next_id=[0x1000]
    def __init__(self):
        self.map={}  # ck -> [lua_key, value]
        self.metatable=None
    def rawget(self, k):
        ck=canon_key(k)
        if ck is None: return None
        e=self.map.get(ck)
        return e[1] if e else None
    def rawset(self, k, v):
        if k is None: raise LuaError(b"table index is nil")
        if is_float(k) and math.isnan(k): raise LuaError(b"table index is NaN")
        ck=canon_key(k, for_set=True)
        lk = int(k) if (is_float(k) and ck[0]=='n') else k
        if v is None:
            self.map.pop(ck, None)
        else:
            if ck in self.map: self.map[ck][1]=v
            else: self.map[ck]=[lk, v]
