class Proto:
    __slots__=('name','source','short_src','linedefined','lastlinedefined','nparams','is_vararg','vararg_name','vararg_slot','code','consts','protos','upvals','maxstack','cell_slots','localvars','lineinfo','param_cells','global_defs')
    def __init__(self):
        self.name=None; self.source=""; self.short_src=""
        self.linedefined=0; self.lastlinedefined=0
        self.nparams=0; self.is_vararg=False; self.vararg_name=None; self.vararg_slot=-1
