        return "-nan" if math.copysign(1.0, v) < 0 else "nan"
    if math.isinf(v): return "inf" if v>0 else "-inf"
    s = fmt_float_g(v, 15)
    try:
        if float(s) != v:
            s = fmt_float_g(v, 17)
    except Exception:
        s = fmt_float_g(v, 17)
    if 'e' not in s and 'E' not in s and '.' not in s and s not in ('inf','-inf','nan','-nan'):
        s += ".0"
    return s

def lua_tostring_basic(v):
    """tostring without metamethod; returns bytes or None"""
    if v is None: return b"nil"
    if v is True: return b"true"
    if v is False: return b"false"
    if is_int(v): return str(v).encode()
    if is_float(v): return lua_num2str(v).encode()
    if isinstance(v, bytes): return v
    if isinstance(v, LuaTable): return ("table: 0x%x" % id(v)).encode()
    if isinstance(v, (LuaFunction, BuiltinFunction)): return ("function: 0x%x" % id(v)).encode()
    if isinstance(v, LuaThread): return ("thread: 0x%x" % id(v)).encode()
    if isinstance(v, UserData):
        d=v.data
        # files print as 'file (closed)' etc handled via their repr hook
        if hasattr(d, 'lua_tostring'): return d.lua_tostring()
        return ("userdata: 0x%x" % id(v)).encode()
    return str(v).encode()

_INT_RE = re.compile(rb'^[ \t\n\v\f\r]*([+-]?)(0[xX][0-9a-fA-F]+|0[xX][0-9a-fA-F]*\.[0-9a-fA-F]*([pP][+-]?[0-9]+)?|0[xX][0-9a-fA-F]+[pP][+-]?[0-9]+|[0-9]+)[ \t\n\v\f\r]*$')
def parse_number_string(s):
    """Parse a Lua numeric string; returns int/float or None."""
    if not isinstance(s, bytes): return None
    t = s.strip(b' \t\n\v\f\r')
    if not t: return None
    # inf / nan words? Lua's strtod accepts 'inf','infinity','nan'
    low = t.lower()
    neg=False
    tt=t
    if tt[:1] in (b'+', b'-'):
        neg = tt[:1]==b'-'; tt=tt[1:]; low=tt.lower()
    if low in (b'inf', b'infinity'):
        return float('-inf') if neg else float('inf')
    if low == b'nan':
        return float('nan')
    # hex
    try:
        if low.startswith(b'0x'):
            body = tt[2:]
            if b'.' in body or b'p' in body.lower():
                # hex float
                val = float.fromhex(tt.decode('ascii'))
                return val
            else:
                if not body or not all(c in b'0123456789abcdefABCDEF' for c in body): return None
                val = int(body, 16)
                if neg: val = -val
                return wrap_int(val)
        # decimal: decide int vs float
        if any(c in tt for c in b'.eE'):
            # float
            val = float(tt.decode('ascii'))
            return val
        else:
            if not tt.isdigit(): return None
            val = int(tt, 10)
            if neg: val=-val
            if INT_MIN <= val <= INT_MAX: return val
            # overflow -> float
            return float(t.decode('ascii'))
    except Exception:
        return None

def str_to_number(v):
    if is_num(v): return v
    if isinstance(v, bytes): return parse_number_string(v)
    return None

