        if op==OP_ADD: return fa+fb
        if op==OP_SUB: return fa-fb
        if op==OP_MUL: return fa*fb
        if op==OP_DIV:
            if fb==0.0:
                if fa==0.0 or math.isnan(fa): return float('nan')
                return math.copysign(float('inf'), fa)*math.copysign(1.0, fb) if False else (float('inf') if (fa>0)==(fb>0 or math.copysign(1,fb)>0) else float('-inf'))
            return fa/fb
        if op==OP_IDIV:
            if fb==0.0:
                if fa==0 or math.isnan(fa): return float('nan')
                return float('inf') if (fa>0)==(math.copysign(1,fb)>0) else float('-inf')
            return float(math.floor(fa/fb)) if not (math.isinf(fa) or math.isnan(fa) or math.isnan(fb)) else (float('nan') if math.isnan(fa/fb) else fa/fb)
        if op==OP_MOD:
            if fb==0.0: return float('nan')
            try:
                r=fa - math.floor(fa/fb)*fb
            except Exception: return float('nan')
            return r
        if op==OP_POW:
            try: return math.pow(fa, fb)
            except OverflowError:
                # sign: negative base odd int exponent
                return float('-inf') if fa<0 and float(fb).is_integer() and int(fb)%2!=0 else float('inf')
            except ValueError: return float('nan')
        return None
    def to_integer_bitwise(self, v, k=None,n=None):
        if is_int(v): return v
        if is_float(v):
            if v==int(v) and INT_MIN<=v<=INT_MAX: return int(v)
            self.rt_error(b"number has no integer representation")
        nv=self.to_number_arith(v)
        if nv is not None:
            if is_int(nv): return nv
            if is_float(nv) and nv==int(nv) and INT_MIN<=nv<=INT_MAX: return int(nv)
            if is_float(nv): self.rt_error(b"number has no integer representation")
        mm=None
        self.rt_error(b"attempt to perform bitwise operation on a %s value%s" % (typename(v).encode(), self.describe_value(v,k,n)))
    def bitwise(self, op, a, b, k1=None,n1=None,k2=None,n2=None):
        ev={OP_BAND:b'__band',OP_BOR:b'__bor',OP_BXOR:b'__bxor',OP_SHL:b'__shl',OP_SHR:b'__shr'}.get(op)
        # try numbers first
        ok=True
        try:
            ia=self.to_integer_bitwise(a,k1,n1); ib=self.to_integer_bitwise(b,k2,n2)
        except LuaError as e:
            # if error is 'number has no integer representation' propagate, else metamethod
            if b"number has no integer representation" in (e.value if isinstance(e.value,bytes) else b""): raise
            ok=False
        if ok:
            if op==OP_BAND: return wrap_int(ia & ib)
            if op==OP_BOR: return wrap_int(ia | ib)
            if op==OP_BXOR: return wrap_int(ia ^ ib)
            if op==OP_SHL:
                if ib>=64 or ib<=-64:
                    return 0 if ib>=0 else 0
                if ib>=0: return wrap_int(ia << ib)
                else: return wrap_int((ia & MASK64) >> (-ib)) if ib>-64 else 0
            if op==OP_SHR:
                if ib>=0:
                    if ib>=64: return 0
                    return wrap_int((ia & MASK64) >> ib) if ia<0 else ia>>ib
                else:
                    if ib<=-64: return 0
                    return wrap_int(ia << (-ib))
        if ev:
            mm=self.get_metamethod(a, ev)
            if mm is None: mm=self.get_metamethod(b, ev)
            if mm is not None:
                r=self.call_value(mm,[a,b],'metamethod',ev[2:]); return r[0] if r else None
        self.to_integer_bitwise(a if False else a,k1,n1)  # raise appropriate
    def unary(self, op, a, k=None,n=None):
        if op==OP_NOT: return not truthy(a)
        if op==OP_UNM:
            na=self.to_number_arith(a)
            if na is not None:
                return wrap_int(-na) if is_int(na) else -na
            mm=self.get_metamethod(a,b'__unm')
            if mm is not None:
                r=self.call_value(mm,[a,a],'metamethod',b'unm'); return r[0] if r else None
            self.arith_error(a,k,n)
        if op==OP_BNOT:
            ev=None
            try: ia=self.to_integer_bitwise(a,k,n)
            except LuaError as e:
                if b"no integer representation" in (e.value if isinstance(e.value,bytes) else b""): raise
                mm=self.get_metamethod(a,b'__bnot')
                if mm is not None:
                    r=self.call_value(mm,[a],'metamethod',b'bnot'); return r[0] if r else None
                raise
            return wrap_int(~ia)
        if op==OP_LEN:
            if isinstance(a, bytes): return len(a)
            mm=self.get_metamethod(a,b'__len')
            if mm is not None:
                r=self.call_value(mm,[a],'metamethod',b'len'); return r[0] if r else None
            if isinstance(a, LuaTable): return self.table_length(a)
            self.rt_error(b"attempt to get length of a %s value%s" % (typename(a).encode(), self.describe_value(a,k,n)))
    def table_length(self, t):
        if t.rawget(1) is None: return 0
        # find border by exponential/binary search
        # check metamethod handled by caller
        lo=1
        # find hi with nil
        hi=1
        while t.rawget(hi) is not None:
            lo=hi; hi*=2
            if hi> (1<<40): break
        # now t[lo]!=nil, t[hi]==nil
        while lo+1<hi:
            mid=(lo+hi)//2
            if t.rawget(mid) is not None: lo=mid
            else: hi=mid
        return lo
    def lua_equals(self, a, b):
        if is_num(a) and is_num(b):
            if is_float(a) and math.isnan(a): return False
            if is_float(b) and math.isnan(b): return False
            return a==b
        if type(a)!=type(b):
            # bool vs int etc; table vs userdata diff
            if isinstance(a, bool) or isinstance(b, bool): return False
            return False
        if isinstance(a, (LuaTable, UserData)):
            if a is b: return True
            mma=self.get_metamethod(a,b'__eq'); mmb=self.get_metamethod(b,b'__eq')
            if mma is not None and mma is mmb:
                r=self.call_value(mma,[a,b],'metamethod',b'eq'); return truthy(r[0]) if r else False
            return False
        if isinstance(a, bytes): return a==b
        return a is b or a==b
    def lua_compare(self, op, a, b, k1=None,n1=None,k2=None,n2=None):
        # op CMP_
        if op in (CMP_EQ, CMP_NE):
            eq=self.lua_equals(a,b); return eq if op==CMP_EQ else not eq
        # lt/le/gt/ge normalize to lt/le on swapped
        if is_num(a) and is_num(b):
            if op==CMP_LT: return a<b
            if op==CMP_LE: return a<=b
            if op==CMP_GT: return a>b
            if op==CMP_GE: return a>=b
        if isinstance(a,bytes) and isinstance(b,bytes):
            if op==CMP_LT: return a<b
            if op==CMP_LE: return a<=b
            if op==CMP_GT: return a>b
            if op==CMP_GE: return a>=b
        # metamethods
        if op==CMP_LT: ev=b'__lt'; x,y=a,b
        elif op==CMP_LE: ev=b'__le'; x,y=a,b
        elif op==CMP_GT: ev=b'__lt'; x,y=b,a
        else: ev=b'__le'; x,y=b,a
        mm=self.get_metamethod(x, ev)
        if mm is None or mm is not self.get_metamethod(y, ev):
            # if le missing but lt present: a<=b == not(b<a)
            if ev==b'__le':
                mmlt=self.get_metamethod(y, b'__lt') if op in (CMP_LE,) else self.get_metamethod(x,b'__lt')
                # for CMP_LE: not (b<a)
                if op==CMP_LE:
                    mm2=self.get_metamethod(b,b'__lt')
                    if mm2 is not None and mm2 is self.get_metamethod(a,b'__lt'):
                        r=self.call_value(mm2,[b,a],'metamethod',b'lt'); return not truthy(r[0]) if r else True
                if op==CMP_GE:
                    mm2=self.get_metamethod(a,b'__lt')
                    if mm2 is not None and mm2 is self.get_metamethod(b,b'__lt'):
                        r=self.call_value(mm2,[a,b],'metamethod',b'lt'); return not truthy(r[0]) if r else True
            bad = a
            self.rt_error(b"attempt to compare %s with %s" % (typename(a).encode(), typename(b).encode()) if not (isinstance(a,(LuaTable,UserData)) and type(a)==type(b)) else b"attempt to compare two %s values" % typename(a).encode())
        r=self.call_value(mm,[x,y],'metamethod',ev[2:]); return truthy(r[0]) if r else False
    def concat_values(self, vals, kinds=None):
        # vals list, evaluate metamethods pairwise lua-style (left to right concat folding)
        # simple: fold from right? lua concats checking each
        res=vals[-1]
        for i in range(len(vals)-2,-1,-1):
            a=vals[i]
            # convert a and res to strings if possible
            sa=a if isinstance(a,bytes) else (lua_num2str(a).encode() if is_num(a) else None)
            sb=res if isinstance(res,bytes) else (lua_num2str(res).encode() if is_num(res) else None)
            if sa is not None and sb is not None:
                res=sa+sb
            else:
                mm=self.get_metamethod(a,b'__concat')
                if mm is None: mm=self.get_metamethod(res,b'__concat')
                if mm is not None:
                    r=self.call_value(mm,[a,res],'metamethod',b'concat'); res=r[0] if r else None
                else:
                    bad=a if sa is None else res
                    self.rt_error(b"attempt to concatenate a %s value%s" % (typename(bad).encode(), b""))
        return res
    def index_value(self, obj, key, kind=None, name=None):
        # repeated __index chain
        cur=obj
        for _ in range(100):
            if isinstance(cur, LuaTable):
                v=cur.rawget(key)
                if v is not None: return v
                mm=cur.metatable.rawget(b'__index') if isinstance(cur.metatable, LuaTable) else None
                if mm is None: return None
                if isinstance(mm, (LuaFunction, BuiltinFunction)) or self.get_metamethod(mm, b'__call') is not None and not isinstance(mm, LuaTable):
                    r=self.call_value(mm,[cur,key],'metamethod',b'index'); return r[0] if r else None
                cur=mm; continue
            else:
                mm=self.get_metamethod(cur, b'__index')
                if mm is None:
                    self.rt_error(b"attempt to index a %s value%s" % (typename(cur).encode(), self.describe_value(cur,kind,name)))
                if isinstance(mm, LuaTable):
                    cur=mm; continue
                r=self.call_value(mm,[cur,key],'metamethod',b'index'); return r[0] if r else None
        self.rt_error(b"'__index' chain too long; possible loop")
    def newindex_value(self, obj, key, value, kind=None, name=None):
        cur=obj
        for _ in range(100):
            if isinstance(cur, LuaTable):
                if cur.rawget(key) is not None:
                    cur.rawset(key, value); return
                mm=cur.metatable.rawget(b'__newindex') if isinstance(cur.metatable, LuaTable) else None
                if mm is None:
                    cur.rawset(key, value); return
                if isinstance(mm, LuaTable):
                    cur=mm; continue
                self.call_value(mm,[cur,key,value],'metamethod',b'newindex'); return
            else:
                mm=self.get_metamethod(cur, b'__newindex')
                if mm is None:
                    self.rt_error(b"attempt to index a %s value%s" % (typename(cur).encode(), self.describe_value(cur,kind,name)))
                if isinstance(mm, LuaTable):
                    cur=mm; continue
                self.call_value(mm,[cur,key,value],'metamethod',b'newindex'); return
        self.rt_error(b"'__newindex' chain too long; possible loop")

    def _seed_random(self):
        # xoshiro256** state seeded like lua: use time/pid/address as entropy if not seeded
        import os as _os
        seed = int(time.time()*1e6) ^ (_os.getpid()<<32) ^ id(self)
        self.set_random_seed(seed, seed>>32)
    def set_random_seed(self, x, y=0):
        # Lua 5.4/5.5 algorithm: state from seeds using splitmix64-ish (l_math.c randseed)
        # Imitate known lua:  n1 = x, n2 = y ...
        def splitmix(state):
            state = (state + 0x9E3779B97F4A7C15) & MASK64
            z=state
            z = ((z ^ (z>>30)) * 0xBF58476D1CE4E5B9) & MASK64
            z = ((z ^ (z>>27)) * 0x94D049BB133111EB) & MASK64
            return state, (z ^ (z>>31)) & MASK64
        # Lua's lua_random seed procedure (from memory): calls ran_init with two integers
        # It initializes state s0..s3 by ???
        s = (x & MASK64) ^ 0x9E3779B97F4A7C15
        vals=[]
        state = s
        # Use splitmix64 to fill 4 words, incorporating y
        state = (x & MASK64) + 0x9E3779B97F4A7C15
        for i in range(4):
            state, v = splitmix(state)
            if i==0: v ^= (y & MASK64)
            vals.append(v)
        if all(v==0 for v in vals): vals[0]=1
        self.random_state=vals
        self.random_seeded=True
        # Lua discards first outputs? It calls nextrand a few times? Project(?) We'll keep.
    def next_random_u64(self):
        s=self.random_state
        result = wrap_int( (((s[1]*5) & MASK64) << 7 | ((s[1]*5) & MASK64) >> 57) * 9 )
        result_u = ((( (s[1]*5) & MASK64) << 7) & MASK64 | (((s[1]*5)&MASK64) >> 57)) * 9 & MASK64
        t = ((s[1] << 17) & MASK64)
        s[2] ^= s[0]; s[3] ^= s[1]; s[1] ^= s[2]; s[0] ^= s[3]
        s[2] ^= t
        s[3] = ((s[3] << 45) & MASK64) | (s[3] >> 19)
        self.random_state=s
        return result_u
    def random_float(self):
        # lua: (nextrand >> 11) * 2^-53
        return (self.next_random_u64() >> 11) * (1.0/(1<<53))

