# ---------- opcodes ----------
(OP_MOVE,OP_LOADK,OP_LOADNIL,OP_GETUPVAL,OP_SETUPVAL,OP_LOADCELL,OP_STORECELL,OP_DECLCELL,
 OP_GETGLOBAL,OP_SETGLOBAL,OP_DEFGLOBAL,OP_NEWTABLE,OP_GETTABLE,OP_SETTABLE,OP_GETFIELD,OP_SETFIELD,OP_SELF,
 OP_ADD,OP_SUB,OP_MUL,OP_MOD,OP_POW,OP_DIV,OP_IDIV,OP_BAND,OP_BOR,OP_BXOR,OP_SHL,OP_SHR,
 OP_UNM,OP_BNOT,OP_NOT,OP_LEN,OP_CONCAT,OP_CMP,OP_JMP,OP_JIF,OP_CALL,OP_TAILCALL,OP_RETURN,OP_VARARG,
 OP_CLOSURE,OP_SETLIST,OP_FORPREP,OP_FORLOOP,OP_TOCLOSE,OP_CLOSETO,OP_MOVEVARARGNAME) = range(48)
CMP_EQ,CMP_LT,CMP_LE,CMP_NE,CMP_GT,CMP_GE = 0,1,2,3,4,5

def truthy(v): return not (v is None or v is False)

class VM:
    def __init__(self):
        self.frames=[]  # Frame/CFrame
        self.G=LuaTable()
        self.registry=LuaTable()
        self.string_meta=LuaTable()
        self.type_metas={}  # typename -> metatable table
        self.warn_enabled=False
        self.gc_running=True
        self.gc_mode='generational'
        self.gc_params={'pause':250,'stepmul':200,'stepsize':9600,'minormul':20,'majorinc':100}
        self.random_state=[0]*4
        self.random_seeded=False
        self.current_thread=None  # LuaThread or None=main
        self.hook=None; self.hook_mask=''; self.hook_count=0; self.hook_counter=0
        self.stdout_file=None; self.stdin_file=None; self.stderr_file=None
        self.package=None
        self.progname="lua"
        self.exit_code=None
        self.modules={}
        self._seed_random()

    # ----- error helpers -----
    def cur_lua_frame(self):
        for f in reversed(self.frames):
            if isinstance(f, Frame): return f
        return None
    def pos_of_frame(self, f):
        if f is None: return b""
        return ("%s:%s: " % (f.proto.short_src, f.line)).encode('utf-8','surrogateescape')
    def rt_error(self, msg):
        if isinstance(msg, str): msg=msg.encode('utf-8','surrogateescape')
        f=self.cur_lua_frame()
        raise LuaError(self.pos_of_frame(f)+msg if f else msg)
    def arg_error(self, idx, fname, msg):
        # msg bytes/str without prefix; add caller position if caller below C frame is Lua
        if isinstance(msg, str): msg=msg.encode('utf-8','surrogateescape')
        detail = b"bad argument #%d to '%s' (%s)" % (idx, fname.encode('utf-8','surrogateescape') if isinstance(fname,str) else fname, msg)
        prefix=b""
        # find top CFrame, frame below it
        for i in range(len(self.frames)-1,-1,-1):
            if isinstance(self.frames[i], CFrame):
                if i>0 and isinstance(self.frames[i-1], Frame):
                    prefix=self.pos_of_frame(self.frames[i-1])
                break
        raise LuaError(prefix+detail)
    def type_error_arg(self, idx, fname, expected, v):
        self.arg_error(idx, fname, b"%s expected, got %s" % (expected.encode(), typename(v).encode()))

    def make_traceback(self, level=0, skip_top=0):
        lines=["stack traceback:"]
        frames=list(self.frames)
        # level: skip levels from top (each frame is a level)
        idx=len(frames)-1-skip_top
        count=0
        entries=[]
        while idx>=0:
            f=frames[idx]
            if isinstance(f, CFrame):
                if f.name:
                    kind = f.name_kind or 'function'
                    entries.append("\t[C]: in %s '%s'" % (kind, f.name.decode('utf-8','surrogateescape') if isinstance(f.name,bytes) else str(f.name)))
                else:
                    entries.append("\t[C]: in ?")
            else:
                proto=f.proto
                if proto.linedefined==0:
                    desc="main chunk"
                elif f.caller_name:
                    kind=f.caller_name_kind or 'function'
                    nm=f.caller_name.decode('utf-8','surrogateescape') if isinstance(f.caller_name,bytes) else str(f.caller_name)
                    desc="%s '%s'" % (kind, nm)
                else:
                    desc="function <%s:%d>" % (proto.short_src, proto.linedefined)
                entries.append("\t%s:%d: in %s" % (proto.short_src, f.line, desc))
            idx-=1
        entries_out=entries
        if len(entries_out)>22:
            entries_out=entries_out[:12]+["\t..."]+entries_out[-9:]
        lines.extend(entries_out)
        # host below main chunk
        if frames and isinstance(frames[0], Frame) and frames[0].proto.linedefined==0:
            lines.append("\t[C]: in ?")
        return "\n".join(lines)

    # ----- metatable helpers -----
    def raw_metatable(self, v):
        if isinstance(v, LuaTable): return v.metatable
        if isinstance(v, UserData): return v.metatable
        if isinstance(v, bytes): return self.string_meta
        if isinstance(v, LuaThread):
            return self.type_metas.get('thread')
        t=typename(v)
        return self.type_metas.get(t)
    def get_metamethod(self, v, name):
        mt=self.raw_metatable(v)
        if isinstance(mt, LuaTable):
            return mt.rawget(name if isinstance(name,bytes) else name.encode())
        return None
    def getmetatable_value(self, v):
        mt=self.raw_metatable(v)
        if isinstance(mt, LuaTable):
            protected=mt.rawget(b'__metatable')
            if protected is not None: return protected
        if mt is None:
            # for string, lua returns string metatable? getmetatable("x") returns string lib metatable
            if isinstance(v, bytes): return self.string_meta
            return None
        return mt

    # ----- calls -----
    def call_value(self, func, args, name_kind=None, name=None):
        if isinstance(func, LuaFunction):
            frame=Frame(); frame.closure=func; frame.proto=func.proto
            frame.caller_name_kind=name_kind; frame.caller_name=name
            sink=[]; frame.return_sink=sink
            depth=len(self.frames)
            self.frames.append(frame)
            self.init_frame(frame, func, args)
            self.execute_until(depth)
            return list(sink)
        if isinstance(func, BuiltinFunction):
            cf=CFrame(name_kind, name, func); self.frames.append(cf)
            try:
                res=func.func(self, list(args))
            finally:
                # pop this frame (it should be on stack; nested frames already cleaned)
                if cf in self.frames: self.frames.remove(cf)
            if res is None: return []
            return list(res)
        mm=self.get_metamethod(func, b'__call')
        if mm is not None:
            return self.call_value(mm, [func]+list(args), 'metamethod', b'call')
        # error: attempt to call
        d=self.describe_value(func, name_kind, name)
        self.rt_error(b"attempt to call a %s value%s" % (typename(func).encode(), d))
    def describe_value(self, v, kind=None, name=None):
        if name is not None:
            nm=name.decode('utf-8','surrogateescape') if isinstance(name,bytes) else str(name)
            k=kind or 'global'
            return (" (%s '%s')" % (k, nm)).encode('utf-8','surrogateescape')
        return b""
    def init_frame(self, frame, closure, args):
        proto=closure.proto; frame.regs=[None]*max(proto.maxstack, proto.nparams+8)
        frame.varargs=[]
        regs=frame.regs
        for i in range(proto.nparams):
            val=args[i] if i < len(args) else None
            if i in proto.cell_slots or i in proto.param_cells:
                regs[i]=Cell(val)
            else:
                regs[i]=val
        if proto.is_vararg:
            frame.varargs=list(args[proto.nparams:])
            if proto.vararg_name is not None and proto.vararg_slot>=0:
                t=LuaTable()
                for i,v in enumerate(frame.varargs): t.rawset(i+1, v)
                # store length border for pack's n field? named vararg table: lua packs as table with ... does it set 'n'? test later; assume array only
                if proto.vararg_slot in proto.cell_slots:
                    regs[proto.vararg_slot]=Cell(t)
                else:
                    regs[proto.vararg_slot]=t
        frame.line=proto.linedefined
        # hook call
    def close_value(self, v, from_error=False):
        if v is None or v is False: return
        mm=self.get_metamethod(v, b'__close')
        if mm is None:
            self.rt_error(b"variable '%s' got a non-closable value" % b"")  # placeholder refined by caller context
        self.call_value(mm, [v]+([True] if from_error else []), 'metamethod', b'close')
    def close_frame_stack(self, frame, to_count=0, from_error=False):
        stack=frame.close_stack
        while len(stack)>to_count:
            ref=stack.pop()
            kind, loc = ref
            if kind=='cell': v=loc.value
            else: v=frame.regs[loc]
            if v is None or v is False: continue
            mm=self.get_metamethod(v, b'__close')
            if mm is None:
                # error at closing
                self.rt_error(b"attempt to call a %s value (metamethod 'close')" % typename(v).encode() if False else b"variable got a value without __close metamethod")
            self.call_value(mm, [v]+([True] if from_error else []), 'metamethod', b'close')

    def execute_until(self, depth):
        try:
            while len(self.frames)>depth:
                frame=self.frames[-1]
                if not isinstance(frame, Frame):
                    break
                self.step_frame(frame)
        except LuaError as e:
            if e.traceback_text is None:
                try: e.traceback_text=self.make_traceback()
                except Exception: e.traceback_text="stack traceback:"
            # unwind frames to depth, closing to-be-closed vars
            while len(self.frames)>depth:
