    def execute_until(self, depth):
        try:
            while len(self.frames)>depth:
                frame=self.frames[-1]
                if not isinstance(frame, Frame):
                    break
                self.step_frame(frame)
        except LuaError as e:
            if e.traceback_text is None:
                try: e.traceback_text=self.make_traceback()
                except Exception: e.traceback_text="stack traceback:"
            # unwind frames to depth, closing to-be-closed vars
            while len(self.frames)>depth:
                f=self.frames.pop()
                if isinstance(f, Frame):
                    try: self.close_frame_stack(f, 0, from_error=True)
                    except LuaError: pass
            raise
        except Exception as e:
            # convert python errors accidentally into Lua stack overflow etc
            while len(self.frames)>depth:
                f=self.frames.pop()
            raise

