        if is_num(a) and is_num(b):
            if is_float(a) and math.isnan(a): return False
            if is_float(b) and math.isnan(b): return False
            return a==b
        if type(a)!=type(b):
            # bool vs int etc; table vs userdata diff
            if isinstance(a, bool) or isinstance(b, bool): return False
            return False
        if isinstance(a, (LuaTable, UserData)):
            if a is b: return True
            mma=self.get_metamethod(a,b'__eq'); mmb=self.get_metamethod(b,b'__eq')
            if mma is not None and mma is mmb:
                r=self.call_value(mma,[a,b],'metamethod',b'eq'); return truthy(r[0]) if r else False
            return False
        if isinstance(a, bytes): return a==b
