    def _seed_random(self):
        # xoshiro256** state seeded like lua: use time/pid/address as entropy if not seeded
        import os as _os
        seed = int(time.time()*1e6) ^ (_os.getpid()<<32) ^ id(self)
        self.set_random_seed(seed, seed>>32)
    def set_random_seed(self, x, y=0):
        # Lua 5.4/5.5 algorithm: state from seeds using splitmix64-ish (l_math.c randseed)
        # Imitate known lua:  n1 = x, n2 = y ...
        def splitmix(state):
            state = (state + 0x9E3779B97F4A7C15) & MASK64
            z=state
            z = ((z ^ (z>>30)) * 0xBF58476D1CE4E5B9) & MASK64
            z = ((z ^ (z>>27)) * 0x94D049BB133111EB) & MASK64
            return state, (z ^ (z>>31)) & MASK64
        # Lua's lua_random seed procedure (from memory): calls ran_init with two integers
        # It initializes state s0..s3 by ???
        s = (x & MASK64) ^ 0x9E3779B97F4A7C15
        vals=[]
        state = s
        # Use splitmix64 to fill 4 words, incorporating y
        state = (x & MASK64) + 0x9E3779B97F4A7C15
        for i in range(4):
            state, v = splitmix(state)
            if i==0: v ^= (y & MASK64)
            vals.append(v)
        if all(v==0 for v in vals): vals[0]=1
        self.random_state=vals
        self.random_seeded=True
        # Lua discards first outputs? It calls nextrand a few times? Project(?) We'll keep.
    def next_random_u64(self):
        s=self.random_state
        result = wrap_int( (((s[1]*5) & MASK64) << 7 | ((s[1]*5) & MASK64) >> 57) * 9 )
        result_u = ((( (s[1]*5) & MASK64) << 7) & MASK64 | (((s[1]*5)&MASK64) >> 57)) * 9 & MASK64
        t = ((s[1] << 17) & MASK64)
        s[2] ^= s[0]; s[3] ^= s[1]; s[1] ^= s[2]; s[0] ^= s[3]
        s[2] ^= t
        s[3] = ((s[3] << 45) & MASK64) | (s[3] >> 19)
        self.random_state=s
        return result_u
    def random_float(self):
        # lua: (nextrand >> 11) * 2^-53
        return (self.next_random_u64() >> 11) * (1.0/(1<<53))

