def utf8_encode_cp(cp):
    if cp<0x80: return bytes([cp])
    if cp<0x800: return bytes([0xC0|(cp>>6),0x80|(cp&0x3F)])
    if cp<0x10000: return bytes([0xE0|(cp>>12),0x80|((cp>>6)&0x3F),0x80|(cp&0x3F)])
    if cp<0x200000: return bytes([0xF0|(cp>>18),0x80|((cp>>12)&0x3F),0x80|((cp>>6)&0x3F),0x80|(cp&0x3F)])
    # Lua utf8 escape allows up to 0x7FFFFFFF using up to 6 byte encoding (original utf8)
    if cp<0x4000000: return bytes([0xF8|(cp>>24),0x80|((cp>>18)&0x3F),0x80|((cp>>12)&0x3F),0x80|((cp>>6)&0x3F),0x80|(cp&0x3F)])
