            return ('upval',line,idx,uv)
        if name==b'_ENV':
            # root env handled; nested parent env should have been created
            idx=ctx.get_upvalue(name)
            if idx is not None: return ('upval',line,idx,None)
        # global
        info=ctx.visible_global(name)
        if ctx.any_global_decl_visible() and info is None:
            self.err(f"variable '{name.decode('utf-8','surrogateescape')}' not declared", line)
        if for_assign and info is not None and info.get('const'):
            self.err(f"attempt to assign to const variable '{name.decode('utf-8','surrogateescape')}'", line)
        envnode=self.resolve_env_ref(line)
        return ('global',line,name,envnode,info)
    def resolve_env_ref(self,line):
        ctx=self.ctx
        var=ctx.find_local(b'_ENV')
        if var is not None: return ('local',line,var)
        idx=ctx.get_upvalue(b'_ENV')
        if idx is not None: return ('upval',line,idx,None)
        # root fallback
        return ('upval',line,ctx.get_upvalue(b'_ENV'),None)
    # ---------- parsing ----------
    def parse_chunk(self):
        ctx=FuncCtx(self,None,0); self.ctx=ctx; ctx.enter()
        fd=ctx.funcdef; fd.source=self.chunkname; fd.display=self.display; fd.is_string=self.is_string; fd.linedefined=0
        body=self.parse_statements({'eof'})
        ctx.leave()
        fd.body=body; fd.lastlinedefined=self.tok().line
        if self.tok().type!='eof': self.err(f"syntax error near {self.token_desc()}")
        return fd
    def at_terminator(self, terms):
        t=self.tok()
        if t.type=='eof': return 'eof' in terms
        if t.type=='kw' and t.value in terms: return True
        return False
    def parse_statements(self, terms):
        stmts=[]
        while not self.at_terminator(terms):
            if self.is_sym(';'): self.adv(); continue
            st=self.parse_statement()
            if st is not None: stmts.append(st)
            if st is not None and st[0]=='return':
                # optional ;
                self.accept_sym(';'); break
        return stmts
    def parse_block_scoped(self, terms):
        self.ctx.enter()
        body=self.parse_statements(terms)
        self.ctx.leave()
        return body
    def parse_statement(self):
        t=self.tok(); line=t.line
        if self.is_kw('do'):
            self.adv(); body=self.parse_block_scoped({'end'}); self.expect_kw('end'); return ('do',line,body)
        if self.is_kw('while'):
            self.adv(); cond=self.parse_expr(); self.expect_kw('do'); body=self.parse_block_scoped({'end'}); self.expect_kw('end'); return ('while',line,cond,body)
        if self.is_kw('repeat'):
            self.adv(); self.ctx.enter(); body=self.parse_statements({'until'}); self.expect_kw('until'); cond=self.parse_expr(); self.ctx.leave(); return ('repeat',line,body,cond)
        if self.is_kw('if'):
            self.adv(); branches=[]
            cond=self.parse_expr(); self.expect_kw('then'); body=self.parse_block_scoped({'elseif','else','end'}); branches.append((cond,body))
            while self.is_kw('elseif'):
                self.adv(); c=self.parse_expr(); self.expect_kw('then'); b=self.parse_block_scoped({'elseif','else','end'}); branches.append((c,b))
            elsebody=None
            if self.accept_kw('else'): elsebody=self.parse_block_scoped({'end'})
            self.expect_kw('end'); return ('if',line,branches,elsebody)
        if self.is_kw('for'):
            return self.parse_for()
        if self.is_kw('local'):
            return self.parse_local()
        if self.is_kw('function'):
            return self.parse_function_statement()
        if self.is_kw('return'):
            self.adv(); exps=[]
            if not self.at_terminator({'end','else','elseif','until','eof'}) and not self.is_sym(';'):
                exps=self.parse_explist()
            return ('return',line,exps)
        if self.is_kw('break'):
            self.adv(); return ('break',line)
        if self.is_kw('goto'):
            self.adv(); nm=self.expect_name(); return ('goto',line,nm.value)
        if self.is_sym('::'):
            self.adv(); nm=self.expect_name(); self.expect_sym('::'); return ('label',line,nm.value)
        # global contextual statement: token 'global' is a name
        if t.type=='name' and t.value==b'global':
            nt=self.peek(1)
            if nt.type=='name' or (nt.type=='sym' and nt.value=='*'):
                return self.parse_global()
        # expression statement: assignment or call
        return self.parse_expr_statement()
    def parse_global(self):
        line=self.tok().line; self.adv()  # global
        if self.accept_sym('*'):
            self.ctx.global_scopes[-1]['wild']=True
            # no assignment allowed (parser will error on following tokens naturally as new statement attempted)
            return ('noop',line)
        names=[]; infos=[]
        envnode=self.resolve_env_ref(line)
        while True:
            nt=self.expect_name(); name=nt.value
            if name==b'_ENV': self.err("_ENV is global when accessing variable '_ENV'", line)  # placeholder; tested later
            attrib=None
            if self.accept_sym('<'):
                at=self.expect_name(); attrib=at.value; self.expect_sym('>')
                if attrib==b'close': self.err("global variables cannot be to-be-closed", line)
                if attrib!=b'const': self.err(f"unknown attribute '{attrib.decode()}'", line)
            info={'const': attrib==b'const'}
            names.append(name); infos.append(info)
            self.ctx.global_scopes[-1]['decls'][name]=info
            if not self.accept_sym(','): break
        exps=[]
        if self.accept_sym('='):
            exps=self.parse_explist()
            return ('globaldef',line,names,exps,envnode)
        return ('noop',line)
    def parse_attrib(self):
        if not self.accept_sym('<'): return None
        at=self.expect_name(); self.expect_sym('>')
        if at.value not in (b'const', b'close'):
            self.err(f"unknown attribute '{at.value.decode()}'")
        return at.value
    def parse_local(self):
        line=self.tok().line; self.adv()
        if self.accept_kw('function'):
            nt=self.expect_name(); var=LocalVar(nt.value)
            self.ctx.scopes[-1][nt.value]=var
            fd=self.parse_funcbody(line)
            fd.debug_name=nt.value
            return ('localfunc',line,var,fd)
        vars=[]
        while True:
            nt=self.expect_name(); attrib=self.parse_attrib()
            vars.append(LocalVar(nt.value, attrib==b'const', attrib==b'close'))
            if not self.accept_sym(','): break
        exps=[]
        if self.accept_sym('='): exps=self.parse_explist()
        # activate scope after exprs
        for v in vars: self.ctx.scopes[-1][v.name]=v
        return ('localdecl',line,vars,exps)
    def parse_function_statement(self):
        line=self.tok().line; self.adv()
        nt=self.expect_name()
        target=self.resolve_name(nt.value, line, for_assign=True)
        method=None
        while self.accept_sym('.'):
            fn=self.expect_name()
            target=('index',line,target,('str',line,fn.value))
        if self.accept_sym(':'):
            fn=self.expect_name(); method=fn.value
            target=('index',line,target,('str',line,fn.value))
        fd=self.parse_funcbody(line, method=method)
        fd.debug_name=method or (target[2].encode() if False else None)
        return ('assign',line,[target],[('func',line,fd)])
    def parse_funcbody(self, line, method=None):
        oldctx=self.ctx
        ctx=FuncCtx(self, oldctx, line); self.ctx=ctx; ctx.enter()
        fd=ctx.funcdef; fd.source=oldctx.funcdef.source; fd.display=self.display; fd.is_string=self.is_string; fd.linedefined=line
        self.expect_sym('(')
        params=[]
        if method is not None:
            sv=LocalVar(b'self', is_param=True); params.append(sv); ctx.scopes[-1][b'self']=sv
        is_vararg=False; vararg_var=None
        if not self.is_sym(')'):
            while True:
                if self.is_sym('...'):
                    self.adv(); is_vararg=True
                    if self.tok().type=='name':
                        nm=self.adv(); vararg_var=LocalVar(nm.value, is_const=True)
                        vararg_var.is_param=True
                        ctx.scopes[-1][nm.value]=vararg_var
                    break
                nt=self.expect_name(); pv=LocalVar(nt.value, is_param=True); params.append(pv); ctx.scopes[-1][nt.value]=pv
                if not self.accept_sym(','): break
        self.expect_sym(')')
        fd.params=params; fd.is_vararg=is_vararg; fd.vararg_var=vararg_var
        body=self.parse_statements({'end'})
        lastline=self.tok().line; self.expect_kw('end')
        ctx.leave(); fd.body=body; fd.lastlinedefined=lastline
        self.ctx=oldctx
        if oldctx is not None: oldctx.funcdef.children.append(fd)
        return fd
    def parse_for(self):
        line=self.tok().line; self.adv()
        nt=self.expect_name()
        if self.accept_sym('='):
            var=LocalVar(nt.value); var.is_loop=True
            e1=self.parse_expr(); self.expect_sym(','); e2=self.parse_expr()
            e3=None
            if self.accept_sym(','): e3=self.parse_expr()
            self.expect_kw('do')
            self.ctx.enter(); self.ctx.scopes[-1][nt.value]=var; body=self.parse_statements({'end'}); self.ctx.leave(); self.expect_kw('end')
            return ('fornum',line,var,e1,e2,e3,body)
        # generic
        vars=[LocalVar(nt.value)]; vars[0].is_loop=True
        while self.accept_sym(','):
            n2=self.expect_name(); v=LocalVar(n2.value); v.is_loop=True; vars.append(v)
        self.expect_kw('in'); exps=self.parse_explist(); self.expect_kw('do')
        self.ctx.enter()
        for v in vars: self.ctx.scopes[-1][v.name]=v
        body=self.parse_statements({'end'}); self.ctx.leave(); self.expect_kw('end')
        return ('forgen',line,vars,exps,body)
    def parse_expr_statement(self):
        line=self.tok().line
        expr=self.parse_suffixed_expr()
        if self.is_sym('=') or self.is_sym(','):
            targets=[expr]
            while self.accept_sym(','): targets.append(self.parse_suffixed_expr())
            self.expect_sym('='); exps=self.parse_explist()
            for tg in targets: self.check_assign_target(tg)
            return ('assign',line,targets,exps)
        if expr[0]!='call':
            self.err(f"syntax error near {self.token_desc()}", line)
        return ('callstmt',line,expr)
    def check_assign_target(self, tg):
        # validate const assignment for locals/upvals/globals already mostly at name resolution time;
        # for suffixed parsing names were resolved without for_assign. Re-check here.
        if tg[0]=='local':
            v=tg[2]
            if v.is_const or v.is_loop: self.err(f"attempt to assign to const variable '{v.name.decode()}'", tg[1])
        elif tg[0]=='upval':
            uv=tg[3] if len(tg)>3 else None
            if uv is not None and (uv.is_const or uv.is_loop): self.err(f"attempt to assign to const variable '{uv.name.decode()}'", tg[1])
        elif tg[0]=='global':
            info=tg[4] if len(tg)>4 else None
            if info and info.get('const'): self.err(f"attempt to assign to const variable '{tg[2].decode()}'", tg[1])
        elif tg[0]=='index':
            pass
        else:
            self.err("syntax error near '='", tg[1] if len(tg)>1 else None)
    def parse_explist(self):
        exps=[self.parse_expr()]
        while self.accept_sym(','): exps.append(self.parse_expr())
        return exps
    # expression parsing
    def parse_expr(self, minpri=0):
        t=self.tok(); line=t.line; left=None
        if t.type=='sym' and t.value in ('-','~','#') or (t.type=='kw' and t.value=='not'):
            op=self.adv().value; operand=self.parse_expr(UNPRI)
            left=('unop',line,op,operand)
        else:
            left=self.parse_simple_expr()
        while True:
            t=self.tok()
            if t.type=='kw' and t.value in ('and','or'): opsym=t.value
            elif t.type=='sym' and t.value in BINPRI: opsym=t.value
            else: break
            if opsym not in BINPRI: break
            lp,rp=BINPRI[opsym]
            if lp<=minpri: break
            self.adv(); right=self.parse_expr(rp)
            left=('binop',t.line,opsym,left,right)
        return left
    def parse_simple_expr(self):
        t=self.tok(); line=t.line
        if t.type=='kw':
            if t.value=='nil': self.adv(); return ('nil',line)
            if t.value=='true': self.adv(); return ('bool',line,True)
            if t.value=='false': self.adv(); return ('bool',line,False)
            if t.value=='function':
                self.adv(); return ('func',line,self.parse_funcbody(line))
        if t.type=='number': self.adv(); return ('num',line,t.value)
        if t.type=='string': self.adv(); return ('str',line,t.value)
        if t.type=='sym' and t.value=='...':
            self.adv()
            if not self.ctx.funcdef.is_vararg and self.ctx.parent is not None or (self.ctx.parent is None and not self.is_main_vararg()):
                # main chunk is vararg
                pass
            if self.ctx.parent is not None and not self.ctx.funcdef.is_vararg:
                self.err("cannot use '...' outside a vararg function near '...'", line)
            return ('vararg',line)
        if t.type=='sym' and t.value=='{':
            return self.parse_table()
        return self.parse_suffixed_expr()
    def is_main_vararg(self): return True
    def parse_suffixed_expr(self):
        t=self.tok(); line=t.line; exp=None
        if t.type=='name':
            self.adv(); exp=self.resolve_name(t.value, line)
        elif self.accept_sym('('):
            e=self.parse_expr(); self.expect_sym(')'); exp=('paren',line,e)
        else:
            self.err(f"unexpected symbol near {self.token_desc()}", line)
        while True:
            if self.accept_sym('.'):
                nm=self.expect_name(); exp=('index',self.tok().line,exp,('str',line,nm.value)); continue
            if self.accept_sym('['):
                k=self.parse_expr(); self.expect_sym(']'); exp=('index',line,exp,k); continue
            if self.accept_sym(':'):
                nm=self.expect_name(); args=self.parse_call_args(); exp=('call',line,('method',line,exp,nm.value),args,nm.value); continue
            if self.is_sym('(') or self.tok().type=='string' or self.is_sym('{'):
                args=self.parse_call_args(); exp=('call',line,exp,args,None); continue
            break
        return exp
    def parse_call_args(self):
        if self.tok().type=='string':
            v=self.adv(); return [('str',v.line,v.value)]
        if self.is_sym('{'):
            return [self.parse_table()]
        self.expect_sym('(')
        args=[]
        if not self.is_sym(')'): args=self.parse_explist()
        self.expect_sym(')'); return args
    def parse_table(self):
        line=self.tok().line; self.expect_sym('{'); items=[]
        while not self.is_sym('}'):
            iline=self.tok().line
            if self.accept_sym('['):
                k=self.parse_expr(); self.expect_sym(']'); self.expect_sym('='); v=self.parse_expr(); items.append(('key',iline,k,v))
            elif self.tok().type=='name' and self.peek(1).type=='sym' and self.peek(1).value=='=':
                nm=self.adv(); self.adv(); v=self.parse_expr(); items.append(('key',iline,('str',iline,nm.value),v))
            else:
                v=self.parse_expr(); items.append(('pos',iline,v))
            if not (self.accept_sym(',') or self.accept_sym(';')): break
            if self.is_sym('}'): break
        self.expect_sym('}'); return ('table',line,items)

