# ================= Lexer / Parser / Codegen =================
KEYWORDS={'and','break','do','else','elseif','end','false','for','function','goto','if','in','local','nil','not','or','repeat','return','then','true','until','while'}
BINPRI={ 'or':(1,1),'and':(2,2), '<':(3,3),'>':(3,3),'<=':(3,3),'>=':(3,3),'~=':(3,3),'==':(3,3),
 '|':(4,4),'~':(5,5),'&':(6,6),'<<':(7,7),'>>':(7,7),'..':(8,7), '+':(9,9),'-':(9,9),
 '*':(10,10),'/':(10,10),'//':(10,10),'%':(10,10),'^':(12,11) }
UNPRI=11

def make_short_src(source, is_string=False):
    # source: string name as stored (may start @ or =)
    if source.startswith('='):
        s=source[1:]
        return s[:60]
    if source.startswith('@'):
        s=source[1:]
        if len(s)>60: return '...'+s[-(60-3):]
        return s
    if is_string:
        # [string "..."] first line truncated
        s=source.split('\n',1)[0]
        if len(source)>45 or '\n' in source:
            return '[string "%s..."]' % s[:42]
        return '[string "%s"]' % s.replace('\n','\\n')
    return source

def utf8_encode_cp(cp):
    if cp<0x80: return bytes([cp])
    if cp<0x800: return bytes([0xC0|(cp>>6),0x80|(cp&0x3F)])
    if cp<0x10000: return bytes([0xE0|(cp>>12),0x80|((cp>>6)&0x3F),0x80|(cp&0x3F)])
    if cp<0x200000: return bytes([0xF0|(cp>>18),0x80|((cp>>12)&0x3F),0x80|((cp>>6)&0x3F),0x80|(cp&0x3F)])
    # Lua utf8 escape allows up to 0x7FFFFFFF using up to 6 byte encoding (original utf8)
    if cp<0x4000000: return bytes([0xF8|(cp>>24),0x80|((cp>>18)&0x3F),0x80|((cp>>12)&0x3F),0x80|((cp>>6)&0x3F),0x80|(cp&0x3F)])
    return bytes([0xFC|(cp>>30),0x80|((cp>>24)&0x3F),0x80|((cp>>18)&0x3F),0x80|((cp>>12)&0x3F),0x80|((cp>>6)&0x3F),0x80|(cp&0x3F)])

class Token:
    __slots__=('type','value','line')
    def __init__(self,t,v,l): self.type=t; self.value=v; self.line=l
    def __repr__(self): return f"Tok({self.type},{self.value!r},{self.line})"

class Lexer:
    def __init__(self, data, display):
        if isinstance(data, bytes): text=data.decode('utf-8','surrogateescape')
        else: text=data
        self.s=text; self.n=len(text); self.i=0; self.line=1; self.display=display
    def err(self,msg,line=None):
        raise SyntaxErr(msg, self.display, self.line if line is None else line)
    def peekch(self, off=0):
        j=self.i+off
        return self.s[j] if j<self.n else ''
    def adv(self):
        ch=self.peekch()
        if ch: self.i+=1
        if ch=='\n': self.line+=1
        return ch
    def tokenize(self):
        toks=[]
        # shebang
        if self.s.startswith('#'):
            while self.i<self.n and self.s[self.i]!='\n': self.i+=1
        while True:
            self.skip_ws_comments()
            line=self.line; ch=self.peekch()
            if not ch:
                toks.append(Token('eof','<eof>',line)); break
            if ch.isalpha() or ch=='_' or ord(ch)>=128:
                j=self.i
                while self.i<self.n:
                    c=self.s[self.i]
                    if c.isalnum() or c=='_' or ord(c)>=128: self.i+=1
                    else: break
                name=self.s[j:self.i]
                if name in KEYWORDS: toks.append(Token('kw',name,line))
                else: toks.append(Token('name',name.encode('utf-8','surrogateescape'),line))
                continue
            if ch.isdigit() or (ch=='.' and self.peekch(1).isdigit()):
                toks.append(Token('number', self.read_number(), line)); continue
            if ch in ('"',"'"):
                toks.append(Token('string', self.read_short_string(ch), line)); continue
            if ch=='[' and (self.peekch(1)=='[' or (self.peekch(1)=='=' and self.long_delim_level(0)>=0)):
                lvl=self.long_bracket_level()
                if lvl is not None:
                    toks.append(Token('string', self.read_long_string(lvl), line)); continue
            # symbols
            three=self.s[self.i:self.i+3]
            two=self.s[self.i:self.i+2]
            if three=='...':
                self.i+=3; toks.append(Token('sym','...',line)); continue
            if two in ('==','~=','<=','>=','//','<<','>>','..','::'):
                self.i+=2; toks.append(Token('sym',two,line)); continue
            if ch in '+-*/%^#&~|<>=(){}[];:,.':
                self.i+=1; toks.append(Token('sym',ch,line)); continue
            self.err(f"unexpected symbol near '{ch}'", line)
        return toks
    def long_bracket_level(self):
        if self.peekch()!='[': return None
        j=self.i+1; lvl=0
        while j<self.n and self.s[j]=='=': lvl+=1; j+=1
        if j<self.n and self.s[j]=='[': return lvl
        return None
    def long_delim_level(self,off): return 0
    def skip_ws_comments(self):
        while True:
            ch=self.peekch()
            if ch and ch in ' \t\v\f\r\n':
                self.adv(); continue
            if ch=='-' and self.peekch(1)=='-':
                # comment
                self.i+=2
                lvl=None
                if self.peekch()=='[':
                    lvl=self.long_bracket_level()
                if lvl is not None:
                    self.read_long_string(lvl, comment=True); continue
                else:
                    while self.i<self.n and self.s[self.i]!='\n': self.i+=1
                    continue
            break
    def read_long_string(self, lvl, comment=False):
        # current at '[' starting long bracket
        start_line=self.line
        self.i+=1
        for _ in range(lvl): self.i+=1
        self.i+=1  # second [
        if self.peekch()=='\r':
            self.i+=1
            if self.peekch()=='\n': self.i+=1; self.line+=1
        elif self.peekch()=='\n': self.adv()
        close=']'+'='*lvl+']'
        end=self.s.find(close, self.i)
        if end<0:
            self.err("unfinished long string near <eof>" if not comment else "unfinished long comment near <eof>", start_line)
        content=self.s[self.i:end]
        self.line+=content.count('\n')
        self.i=end+len(close)
        return content.encode('utf-8','surrogateescape')
    def read_short_string(self, quote):
        start_line=self.line; self.i+=1; out=bytearray()
        while True:
            ch=self.peekch()
            if not ch:
                self.err("unfinished string near <eof>", start_line)
            if ch=='\n' or ch=='\r':
                self.err("unfinished string near <eof>", start_line)
            if ch==quote:
                self.i+=1; break
            if ch=='\\':
                self.i+=1; e=self.peekch()
                if not e: self.err("unfinished string near <eof>", start_line)
                if e=='\n': self.adv(); out.append(10); continue
                if e=='\r':
                    self.i+=1
                    if self.peekch()=='\n': self.i+=1
                    self.line+=1; out.append(10); continue
                escmap={'a':7,'b':8,'f':12,'n':10,'r':13,'t':9,'v':11,'\\':92,'"':34,"'":39}
                if e in escmap: out.append(escmap[e]); self.i+=1; continue
                if e=='x':
                    self.i+=1; h=self.s[self.i:self.i+2]
                    if len(h)<2 or any(c not in '0123456789abcdefABCDEF' for c in h): self.err("hexadecimal digit expected")
                    out.append(int(h,16)); self.i+=2; continue
                if e=='z':
                    self.i+=1
                    while self.i<self.n and self.s[self.i] in ' \t\v\f\r\n':
                        if self.s[self.i]=='\n': self.line+=1
                        self.i+=1
                    continue
                if e=='u':
                    self.i+=1
                    if self.peekch()!='{': self.err("missing '{' in \\u escape")
                    end=self.s.find('}', self.i)
                    if end<0: self.err("missing '}' in \\u escape")
                    hexpart=self.s[self.i+1:end]
                    try: cp=int(hexpart,16)
                    except: self.err("invalid UTF-8 codepoint")
                    if cp>0x7FFFFFFF: self.err("UTF-8 value too large")
                    out.extend(utf8_encode_cp(cp)); self.i=end+1; continue
                if e.isdigit():
                    j=self.i; digits=''
                    while j<self.n and len(digits)<3 and self.s[j].isdigit(): digits+=self.s[j]; j+=1
                    val=int(digits)
                    if val>255: self.err("decimal escape too large")
                    out.append(val); self.i=j; continue
                self.err(f"invalid escape sequence near '\\{e}'")
            else:
                out.extend(ch.encode('utf-8','surrogateescape')); self.adv()
        return bytes(out)
    def read_number(self):
        start=self.i
        # consume as lua: alnum . _ and exponent sign
        while self.i<self.n:
            c=self.s[self.i]
            if c.isalnum() or c in '._':
                self.i+=1
                if c in 'eEpP' and self.i<self.n and self.s[self.i] in '+-':
                    self.i+=1
                continue
            break
        text=self.s[start:self.i]
        val=parse_number_literal(text)
        if val is None: self.err(f"malformed number near '{text}'")
        return val

def parse_number_literal(text):
    try:
        low=text.lower()
        if low.startswith('0x'):
            body=text[2:]
            if '.' in body or 'p' in body.lower():
                return float.fromhex(text)
            if not body: return None
            return wrap_int(int(body,16))
        if any(c in text for c in '.eE'):
            return float(text)
        val=int(text,10)
        if INT_MIN<=val<=INT_MAX: return val
        return float(text)
    except Exception:
        return None

class LocalVar:
    _counter=[0]
    __slots__=('name','is_const','is_close','captured','slot','is_param','is_loop','id')
    def __init__(self,name,is_const=False,is_close=False,is_param=False):
        self.name=name; self.is_const=is_const; self.is_close=is_close; self.captured=False; self.slot=-1; self.is_param=is_param; self.is_loop=False
        LocalVar._counter[0]+=1; self.id=LocalVar._counter[0]

class FuncDef:
    __slots__=('ctx','body','linedefined','lastlinedefined','source','display','is_string','debug_name','params','is_vararg','vararg_var','children')
    def __init__(self):
        self.body=[]; self.linedefined=0; self.lastlinedefined=0; self.debug_name=None; self.params=[]; self.is_vararg=False; self.vararg_var=None; self.children=[]

class FuncCtx:
    def __init__(self, parser, parent, linedefined):
        self.parser=parser; self.parent=parent; self.linedefined=linedefined
        self.scopes=[]; self.global_scopes=[]
        self.upval_map={}; self.upval_descs=[]; self.upval_vars=[]  # parallel to descs: LocalVar or None
        self.funcdef=FuncDef(); self.funcdef.ctx=self
        if parent is None:
            self.global_base={}; self.global_base_wild=False
        else:
            # snapshot visible globals of parent chain at creation
            base=dict(parent.global_base); wild=parent.global_base_wild
            for gs in parent.global_scopes:
                for k,v in gs['decls'].items(): base[k]=v
                if gs['wild']: wild=True
            self.global_base=base; self.global_base_wild=wild
    def enter(self):
        self.scopes.append({}); self.global_scopes.append({'decls':{},'wild':False})
    def leave(self):
        self.scopes.pop(); self.global_scopes.pop()
    def visible_global(self, name):
        for gs in reversed(self.global_scopes):
            if name in gs['decls']: return gs['decls'][name]
            if gs['wild']: return {'const':False,'wild':True}
        if name in self.global_base: return self.global_base[name]
        if self.global_base_wild: return {'const':False,'wild':True}
        return None
    def any_global_decl_visible(self):
        for gs in self.global_scopes:
            if gs['decls'] or gs['wild']: return True
        return bool(self.global_base or self.global_base_wild)
    def find_local(self, name):
        for sc in reversed(self.scopes):
            if name in sc: return sc[name]
        return None
    def get_upvalue(self, name):
        # returns index in this ctx or None (creating through parents if possible); not for root globals
        if name in self.upval_map: return self.upval_map[name]
        if self.parent is None:
            if name==b'_ENV':
                idx=len(self.upval_descs); self.upval_map[name]=idx; self.upval_descs.append((name,'env',0)); self.upval_vars.append(None); return idx
            return None
        # ask parent: local?
        p=self.parent
        var=p.find_local(name)
        if var is not None:
            var.captured=True
            idx=len(self.upval_descs); self.upval_map[name]=idx; self.upval_descs.append((name,'local',var)); self.upval_vars.append(var); return idx
        pidx=p.get_upvalue(name)
        if pidx is not None:
            idx=len(self.upval_descs); self.upval_map[name]=idx; self.upval_descs.append((name,'upval',pidx)); self.upval_vars.append(p.upval_vars[pidx] if pidx < len(p.upval_vars) else None); return idx
        if name==b'_ENV':
            # parent creates env (handled above in recursion, but root reached)
            return None
        return None

class Parser:
    def __init__(self, data, chunkname, display, is_string=False):
        self.lexer=Lexer(data, display); self.toks=self.lexer.tokenize(); self.pos=0
        self.display=display; self.chunkname=chunkname; self.is_string=is_string
        self.ctx=None; self.all_funcdefs=[]
    # token utils
    def tok(self): return self.toks[self.pos]
    def peek(self,off=0):
        j=min(self.pos+off,len(self.toks)-1); return self.toks[j]
    def adv(self):
        t=self.toks[self.pos]
        if self.pos<len(self.toks)-1: self.pos+=1
        return t
    def is_kw(self,w): 
        t=self.tok(); return t.type=='kw' and t.value==w
    def is_sym(self,w):
        t=self.tok(); return t.type=='sym' and t.value==w
    def accept_kw(self,w):
        if self.is_kw(w): self.adv(); return True
        return False
    def accept_sym(self,w):
        if self.is_sym(w): self.adv(); return True
        return False
    def expect_kw(self,w):
        if not self.accept_kw(w): self.err_expected(f"'{w}'")
    def expect_sym(self,w):
        if not self.accept_sym(w): self.err_expected(f"'{w}'")
    def token_desc(self,t=None):
        t=t or self.tok()
        if t.type=='eof': return '<eof>'
        if t.type=='string': return "'"+t.value.decode('utf-8','backslashreplace')[:20]+"'"
        if t.type=='name': return "'"+t.value.decode('utf-8','backslashreplace')+"'"
        return f"'{t.value}'"
    def err(self,msg,line=None):
        raise SyntaxErr(msg,self.display, self.tok().line if line is None else line)
    def err_expected(self, what):
        self.err(f"{what} expected near {self.token_desc()}")
    def expect_name(self):
        t=self.tok()
        if t.type!='name': self.err_expected("'<name>'")
        self.adv(); return t
    # ---------- name resolution ----------
    def resolve_name(self, name, line, for_assign=False):
        ctx=self.ctx
        var=ctx.find_local(name)
        if var is not None:
            if for_assign and (var.is_const or var.is_loop): self.err(f"attempt to assign to const variable '{name.decode('utf-8','surrogateescape')}'", line)
            return ('local',line,var)
        if name in ctx.upval_map:
            idx=ctx.upval_map[name]; uv=ctx.upval_vars[idx] if idx<len(ctx.upval_vars) else None
            if for_assign and uv is not None and (uv.is_const or uv.is_loop): self.err(f"attempt to assign to const variable '{name.decode('utf-8','surrogateescape')}'", line)
            return ('upval',line,idx,uv)
        # try create upvalue via parents (excluding _ENV special? includes)
        idx=ctx.get_upvalue(name)
        if idx is not None:
            # get_upvalue for a non-_ENV name from root returns None, so fine
            # but need ensure this wasn't a fresh env for a normal name: get_upvalue only gives env for _ENV
            uv=ctx.upval_vars[idx] if idx<len(ctx.upval_vars) else None
            if for_assign and uv is not None and (uv.is_const or uv.is_loop): self.err(f"attempt to assign to const variable '{name.decode('utf-8','surrogateescape')}'", line)
            return ('upval',line,idx,uv)
        if name==b'_ENV':
            # root env handled; nested parent env should have been created
            idx=ctx.get_upvalue(name)
            if idx is not None: return ('upval',line,idx,None)
        # global
        info=ctx.visible_global(name)
        if ctx.any_global_decl_visible() and info is None:
            self.err(f"variable '{name.decode('utf-8','surrogateescape')}' not declared", line)
        if for_assign and info is not None and info.get('const'):
            self.err(f"attempt to assign to const variable '{name.decode('utf-8','surrogateescape')}'", line)
        envnode=self.resolve_env_ref(line)
        return ('global',line,name,envnode,info)
    def resolve_env_ref(self,line):
        ctx=self.ctx
        var=ctx.find_local(b'_ENV')
        if var is not None: return ('local',line,var)
        idx=ctx.get_upvalue(b'_ENV')
        if idx is not None: return ('upval',line,idx,None)
        # root fallback
        return ('upval',line,ctx.get_upvalue(b'_ENV'),None)
    # ---------- parsing ----------
    def parse_chunk(self):
        ctx=FuncCtx(self,None,0); self.ctx=ctx; ctx.enter()
        fd=ctx.funcdef; fd.source=self.chunkname; fd.display=self.display; fd.is_string=self.is_string; fd.linedefined=0
        body=self.parse_statements({'eof'})
        ctx.leave()
        fd.body=body; fd.lastlinedefined=self.tok().line
        if self.tok().type!='eof': self.err(f"syntax error near {self.token_desc()}")
        return fd
    def at_terminator(self, terms):
        t=self.tok()
        if t.type=='eof': return 'eof' in terms
        if t.type=='kw' and t.value in terms: return True
        return False
    def parse_statements(self, terms):
        stmts=[]
        while not self.at_terminator(terms):
            if self.is_sym(';'): self.adv(); continue
            st=self.parse_statement()
            if st is not None: stmts.append(st)
            if st is not None and st[0]=='return':
                # optional ;
                self.accept_sym(';'); break
        return stmts
    def parse_block_scoped(self, terms):
        self.ctx.enter()
        body=self.parse_statements(terms)
        self.ctx.leave()
        return body
    def parse_statement(self):
        t=self.tok(); line=t.line
        if self.is_kw('do'):
            self.adv(); body=self.parse_block_scoped({'end'}); self.expect_kw('end'); return ('do',line,body)
        if self.is_kw('while'):
            self.adv(); cond=self.parse_expr(); self.expect_kw('do'); body=self.parse_block_scoped({'end'}); self.expect_kw('end'); return ('while',line,cond,body)
        if self.is_kw('repeat'):
            self.adv(); self.ctx.enter(); body=self.parse_statements({'until'}); self.expect_kw('until'); cond=self.parse_expr(); self.ctx.leave(); return ('repeat',line,body,cond)
        if self.is_kw('if'):
            self.adv(); branches=[]
            cond=self.parse_expr(); self.expect_kw('then'); body=self.parse_block_scoped({'elseif','else','end'}); branches.append((cond,body))
            while self.is_kw('elseif'):
                self.adv(); c=self.parse_expr(); self.expect_kw('then'); b=self.parse_block_scoped({'elseif','else','end'}); branches.append((c,b))
            elsebody=None
            if self.accept_kw('else'): elsebody=self.parse_block_scoped({'end'})
            self.expect_kw('end'); return ('if',line,branches,elsebody)
        if self.is_kw('for'):
            return self.parse_for()
        if self.is_kw('local'):
            return self.parse_local()
        if self.is_kw('function'):
            return self.parse_function_statement()
        if self.is_kw('return'):
            self.adv(); exps=[]
            if not self.at_terminator({'end','else','elseif','until','eof'}) and not self.is_sym(';'):
                exps=self.parse_explist()
            return ('return',line,exps)
        if self.is_kw('break'):
            self.adv(); return ('break',line)
        if self.is_kw('goto'):
            self.adv(); nm=self.expect_name(); return ('goto',line,nm.value)
        if self.is_sym('::'):
            self.adv(); nm=self.expect_name(); self.expect_sym('::'); return ('label',line,nm.value)
        # global contextual statement: token 'global' is a name
        if t.type=='name' and t.value==b'global':
            nt=self.peek(1)
            if nt.type=='name' or (nt.type=='sym' and nt.value=='*'):
                return self.parse_global()
        # expression statement: assignment or call
        return self.parse_expr_statement()
    def parse_global(self):
        line=self.tok().line; self.adv()  # global
        if self.accept_sym('*'):
            self.ctx.global_scopes[-1]['wild']=True
            # no assignment allowed (parser will error on following tokens naturally as new statement attempted)
            return ('noop',line)
        names=[]; infos=[]
        envnode=self.resolve_env_ref(line)
        while True:
            nt=self.expect_name(); name=nt.value
            if name==b'_ENV': self.err("_ENV is global when accessing variable '_ENV'", line)  # placeholder; tested later
            attrib=None
            if self.accept_sym('<'):
                at=self.expect_name(); attrib=at.value; self.expect_sym('>')
                if attrib==b'close': self.err("global variables cannot be to-be-closed", line)
                if attrib!=b'const': self.err(f"unknown attribute '{attrib.decode()}'", line)
            info={'const': attrib==b'const'}
            names.append(name); infos.append(info)
            self.ctx.global_scopes[-1]['decls'][name]=info
            if not self.accept_sym(','): break
        exps=[]
        if self.accept_sym('='):
            exps=self.parse_explist()
            return ('globaldef',line,names,exps,envnode)
        return ('noop',line)
    def parse_attrib(self):
        if not self.accept_sym('<'): return None
        at=self.expect_name(); self.expect_sym('>')
        if at.value not in (b'const', b'close'):
            self.err(f"unknown attribute '{at.value.decode()}'")
        return at.value
    def parse_local(self):
        line=self.tok().line; self.adv()
        if self.accept_kw('function'):
            nt=self.expect_name(); var=LocalVar(nt.value)
            self.ctx.scopes[-1][nt.value]=var
            fd=self.parse_funcbody(line)
            fd.debug_name=nt.value
            return ('localfunc',line,var,fd)
        vars=[]
        while True:
            nt=self.expect_name(); attrib=self.parse_attrib()
            vars.append(LocalVar(nt.value, attrib==b'const', attrib==b'close'))
            if not self.accept_sym(','): break
        exps=[]
        if self.accept_sym('='): exps=self.parse_explist()
        # activate scope after exprs
        for v in vars: self.ctx.scopes[-1][v.name]=v
        return ('localdecl',line,vars,exps)
    def parse_function_statement(self):
        line=self.tok().line; self.adv()
        nt=self.expect_name()
        target=self.resolve_name(nt.value, line, for_assign=True)
        method=None
        while self.accept_sym('.'):
            fn=self.expect_name()
            target=('index',line,target,('str',line,fn.value))
        if self.accept_sym(':'):
            fn=self.expect_name(); method=fn.value
            target=('index',line,target,('str',line,fn.value))
        fd=self.parse_funcbody(line, method=method)
        fd.debug_name=method or (target[2].encode() if False else None)
        return ('assign',line,[target],[('func',line,fd)])
    def parse_funcbody(self, line, method=None):
        oldctx=self.ctx
        ctx=FuncCtx(self, oldctx, line); self.ctx=ctx; ctx.enter()
        fd=ctx.funcdef; fd.source=oldctx.funcdef.source; fd.display=self.display; fd.is_string=self.is_string; fd.linedefined=line
        self.expect_sym('(')
        params=[]
        if method is not None:
            sv=LocalVar(b'self', is_param=True); params.append(sv); ctx.scopes[-1][b'self']=sv
        is_vararg=False; vararg_var=None
        if not self.is_sym(')'):
            while True:
                if self.is_sym('...'):
                    self.adv(); is_vararg=True
                    if self.tok().type=='name':
                        nm=self.adv(); vararg_var=LocalVar(nm.value, is_const=True)
                        vararg_var.is_param=True
                        ctx.scopes[-1][nm.value]=vararg_var
                    break
                nt=self.expect_name(); pv=LocalVar(nt.value, is_param=True); params.append(pv); ctx.scopes[-1][nt.value]=pv
                if not self.accept_sym(','): break
        self.expect_sym(')')
        fd.params=params; fd.is_vararg=is_vararg; fd.vararg_var=vararg_var
        body=self.parse_statements({'end'})
        lastline=self.tok().line; self.expect_kw('end')
        ctx.leave(); fd.body=body; fd.lastlinedefined=lastline
        self.ctx=oldctx
        if oldctx is not None: oldctx.funcdef.children.append(fd)
        return fd
    def parse_for(self):
        line=self.tok().line; self.adv()
        nt=self.expect_name()
        if self.accept_sym('='):
            var=LocalVar(nt.value); var.is_loop=True
            e1=self.parse_expr(); self.expect_sym(','); e2=self.parse_expr()
            e3=None
            if self.accept_sym(','): e3=self.parse_expr()
            self.expect_kw('do')
            self.ctx.enter(); self.ctx.scopes[-1][nt.value]=var; body=self.parse_statements({'end'}); self.ctx.leave(); self.expect_kw('end')
            return ('fornum',line,var,e1,e2,e3,body)
        # generic
        vars=[LocalVar(nt.value)]; vars[0].is_loop=True
        while self.accept_sym(','):
            n2=self.expect_name(); v=LocalVar(n2.value); v.is_loop=True; vars.append(v)
        self.expect_kw('in'); exps=self.parse_explist(); self.expect_kw('do')
        self.ctx.enter()
        for v in vars: self.ctx.scopes[-1][v.name]=v
        body=self.parse_statements({'end'}); self.ctx.leave(); self.expect_kw('end')
        return ('forgen',line,vars,exps,body)
    def parse_expr_statement(self):
        line=self.tok().line
        expr=self.parse_suffixed_expr()
        if self.is_sym('=') or self.is_sym(','):
            targets=[expr]
            while self.accept_sym(','): targets.append(self.parse_suffixed_expr())
            self.expect_sym('='); exps=self.parse_explist()
            for tg in targets: self.check_assign_target(tg)
            return ('assign',line,targets,exps)
        if expr[0]!='call':
            self.err(f"syntax error near {self.token_desc()}", line)
        return ('callstmt',line,expr)
    def check_assign_target(self, tg):
        # validate const assignment for locals/upvals/globals already mostly at name resolution time;
        # for suffixed parsing names were resolved without for_assign. Re-check here.
        if tg[0]=='local':
            v=tg[2]
            if v.is_const or v.is_loop: self.err(f"attempt to assign to const variable '{v.name.decode()}'", tg[1])
        elif tg[0]=='upval':
            uv=tg[3] if len(tg)>3 else None
            if uv is not None and (uv.is_const or uv.is_loop): self.err(f"attempt to assign to const variable '{uv.name.decode()}'", tg[1])
        elif tg[0]=='global':
            info=tg[4] if len(tg)>4 else None
            if info and info.get('const'): self.err(f"attempt to assign to const variable '{tg[2].decode()}'", tg[1])
        elif tg[0]=='index':
            pass
        else:
            self.err("syntax error near '='", tg[1] if len(tg)>1 else None)
    def parse_explist(self):
        exps=[self.parse_expr()]
        while self.accept_sym(','): exps.append(self.parse_expr())
        return exps
    # expression parsing
    def parse_expr(self, minpri=0):
        t=self.tok(); line=t.line; left=None
        if t.type=='sym' and t.value in ('-','~','#') or (t.type=='kw' and t.value=='not'):
            op=self.adv().value; operand=self.parse_expr(UNPRI)
            left=('unop',line,op,operand)
        else:
            left=self.parse_simple_expr()
        while True:
            t=self.tok()
            if t.type=='kw' and t.value in ('and','or'): opsym=t.value
            elif t.type=='sym' and t.value in BINPRI: opsym=t.value
            else: break
            if opsym not in BINPRI: break
            lp,rp=BINPRI[opsym]
            if lp<=minpri: break
            self.adv(); right=self.parse_expr(rp)
            left=('binop',t.line,opsym,left,right)
        return left
    def parse_simple_expr(self):
        t=self.tok(); line=t.line
        if t.type=='kw':
            if t.value=='nil': self.adv(); return ('nil',line)
            if t.value=='true': self.adv(); return ('bool',line,True)
            if t.value=='false': self.adv(); return ('bool',line,False)
            if t.value=='function':
                self.adv(); return ('func',line,self.parse_funcbody(line))
        if t.type=='number': self.adv(); return ('num',line,t.value)
        if t.type=='string': self.adv(); return ('str',line,t.value)
        if t.type=='sym' and t.value=='...':
            self.adv()
            if not self.ctx.funcdef.is_vararg and self.ctx.parent is not None or (self.ctx.parent is None and not self.is_main_vararg()):
                # main chunk is vararg
                pass
            if self.ctx.parent is not None and not self.ctx.funcdef.is_vararg:
                self.err("cannot use '...' outside a vararg function near '...'", line)
            return ('vararg',line)
        if t.type=='sym' and t.value=='{':
            return self.parse_table()
        return self.parse_suffixed_expr()
    def is_main_vararg(self): return True
    def parse_suffixed_expr(self):
        t=self.tok(); line=t.line; exp=None
        if t.type=='name':
            self.adv(); exp=self.resolve_name(t.value, line)
        elif self.accept_sym('('):
            e=self.parse_expr(); self.expect_sym(')'); exp=('paren',line,e)
        else:
            self.err(f"unexpected symbol near {self.token_desc()}", line)
        while True:
            if self.accept_sym('.'):
                nm=self.expect_name(); exp=('index',self.tok().line,exp,('str',line,nm.value)); continue
            if self.accept_sym('['):
                k=self.parse_expr(); self.expect_sym(']'); exp=('index',line,exp,k); continue
            if self.accept_sym(':'):
                nm=self.expect_name(); args=self.parse_call_args(); exp=('call',line,('method',line,exp,nm.value),args,nm.value); continue
            if self.is_sym('(') or self.tok().type=='string' or self.is_sym('{'):
                args=self.parse_call_args(); exp=('call',line,exp,args,None); continue
            break
        return exp
    def parse_call_args(self):
        if self.tok().type=='string':
            v=self.adv(); return [('str',v.line,v.value)]
        if self.is_sym('{'):
            return [self.parse_table()]
        self.expect_sym('(')
        args=[]
        if not self.is_sym(')'): args=self.parse_explist()
        self.expect_sym(')'); return args
    def parse_table(self):
        line=self.tok().line; self.expect_sym('{'); items=[]
