        if tag=='globaldef':
            names=st[2]; exps=st[3]; base=self.temp_n; fixed,var=self.compile_explist(exps,base); self.emit(OP_ADJUST,base,len(names),fixed,1 if var else 0,line=line)
            mode,idx=self.env_operands(st[4])
            for i,nm in enumerate(names): self.emit(OP_DEFGLOBAL,self.const(nm),base+i,mode,idx,line=line)
            return
        if tag=='return':
            exps=st[2]; base=self.temp_n
            if not exps: self.emit(OP_RETURN,0,0,line=line); return
            fixed,var=self.compile_explist(exps,base); n = fixed if not var else -(fixed)-1
