            for e in ends: self.patch(e,len(self.code)) if self.code[e][0]==OP_JMP else None
            return
        if tag=='while':
            start=len(self.code); r=self.alloc_temp(); self.exp(st[2],r); jf=self.emit(OP_JIF,r,True,0,-1,line=line)
            loop=LoopCtx(self.close_depth); self.loops.append(loop)
