                else:
                    obj=self.alloc_temp(); self.exp(tg[2],obj); key=self.alloc_temp(); self.exp(tg[3],key); preps.append(('index',obj,key))
            else: preps.append(('var',tg))
        base=self.temp_n; fixed,var=self.compile_explist(exps,base); self.emit(OP_ADJUST,base,len(targets),fixed,1 if var else 0,line=line)
        for i,pr in enumerate(preps):
            src=base+i
            if pr[0]=='var': self.store_var(pr[1],src)
            elif pr[0]=='field': self.emit(OP_SETFIELD,pr[1],pr[2],src,line=line)
            else: self.emit(OP_SETTABLE,pr[1],pr[2],src,line=line)
    def compile_fornum(self,st):
        line,var,e1,e2,e3,body=st[1],st[2],st[3],st[4],st[5],st[6]
        saved=self.nactvar; base=self.nactvar; self.nactvar+=3; self.touch(base+2)
        self.exp(e1,base); self.exp(e2,base+1)
        if e3: self.exp(e3,base+2)
        else: self.emit(OP_LOADK,base+2,self.const(1),line=line)
        blk=self.enter_block(); slot=self.activate(var)
        prep=self.emit(OP_FORPREP,base,0,1 if var.captured else 0,line=line)
        loop=LoopCtx(blk.start_close); self.loops.append(loop)
        self.compile_statements(body)
        # close body locals above loop var
        if self.close_depth>blk.start_close: self.emit(OP_CLOSETO,blk.start_close,line=line); self.close_depth=blk.start_close
        self.pop_vars_above(1)
        loopinst=self.emit(OP_FORLOOP,base,len(self.code),1 if var.captured else 0,line=line)
        # FORLOOP target is body start; body start is first instruction after FORPREP
        self.code[loopinst][2]=prep+1
        self.loops.pop(); self.exit_block(blk,emit_close=False)
        self.nactvar=saved; self.temp_n=saved
        self.patch(prep,len(self.code))
        for b in loop.breaks: self.patch(b,len(self.code))
    def compile_forgen(self,st):
        line,vars,exps,body=st[1],st[2],st[3],st[4]
        saved=self.nactvar; base=self.nactvar; self.nactvar+=4; self.touch(base+3)
        fixed,var=self.compile_explist(exps,base); self.emit(OP_ADJUST,base,4,fixed,1 if var else 0,line=line)
        start_close=self.close_depth
        blk=self.enter_block()
        for v in vars: self.activate(v)
        self.emit(OP_TOCLOSE,base+3,0,line=line); self.close_depth+=1
        loop=LoopCtx(start_close+1); self.loops.append(loop)
        start=len(self.code)
        result_base=max(self.temp_n,self.nactvar)
        self.emit(OP_CALL,base,2,len(vars),result_base,line=line,kind='function',name=None)
