            else: self.emit(OP_MOVE,v.slot,src,line=line)
        self.emit(OP_MOVE,base+2,result_base,line=line)
        self.compile_statements(body)
        if self.close_depth>start_close+1: self.emit(OP_CLOSETO,start_close+1,line=line); self.close_depth=start_close+1
        self.pop_vars_above(len(vars))
        self.emit(OP_JMP,start,-1,line=line)
        cleanup=len(self.code); self.patch(jf,cleanup)
        self.emit(OP_CLOSETO,start_close,line=line); self.close_depth=start_close
        self.loops.pop(); self.exit_block(blk,emit_close=False)
        self.nactvar=saved; self.temp_n=saved
        for b in loop.breaks: self.patch(b,cleanup)

