# ---------- string patterns ----------
PAT_CLASSES=b'acdg lpsuwx'  # not used directly
def pat_class_match(c, cl):
    # cl is a byte int of class letter (lowercase indicates class)
    lower=chr(cl).lower().encode()[0]
    res=False
    if lower==ord('a'): res=(65<=c<=90 or 97<=c<=122)
    elif lower==ord('c'): res=(c<32 or c==127)
    elif lower==ord('d'): res=(48<=c<=57)
    elif lower==ord('g'): res=(33<=c<=126)
    elif lower==ord('l'): res=(97<=c<=122)
    elif lower==ord('p'): res=(33<=c<=126 and not (48<=c<=57 or 65<=c<=90 or 97<=c<=122))
    elif lower==ord('s'): res=(c in b' \t\n\v\f\r')
    elif lower==ord('u'): res=(65<=c<=90)
    elif lower==ord('w'): res=(48<=c<=57 or 65<=c<=90 or 97<=c<=122)
    elif lower==ord('x'): res=(48<=c<=57 or 65<=c<=70 or 97<=c<=102)
    elif lower==ord('z'): res=(c==0)
    else: return None
    if cl!=lower: res=not res
    return res

class PatternError(Exception): pass
class Pattern:
    def __init__(self, pat):
        if not isinstance(pat,bytes): raise PatternError("pattern not string")
        self.pat=pat; self.tokens=[]; self.ncaps=0; self.parse()
    def parse(self):
        p=self.pat; i=0; n=len(p); anchored=False
        if i<n and p[i:i+1]==b'^': anchored=True; i+=1
        self.anchored=anchored
        toks=[]
        while i<n:
            start=i
            c=p[i]
            if c==ord('('):
                if i+1<n and p[i+1]==ord(')'):
                    cap=self.ncaps; self.ncaps+=1; toks.append(('poscap',cap)); i+=2
                else:
                    cap=self.ncaps; self.ncaps+=1; toks.append(('open',cap)); i+=1
                continue
            if c==ord(')'):
                toks.append(('close',None)); i+=1; continue
            if c==ord('$') and i==n-1:
                toks.append(('end',None)); i+=1; continue
            # one pattern item
            item=None
            if c==ord('%'):
                if i+1>=n: raise PatternError("malformed pattern (ends with '%')")
                d=p[i+1]
                if d==ord('b'):
                    if i+3>=n: raise PatternError("malformed pattern (missing arguments to '%b')")
                    item=('bal',p[i+2],p[i+3]); i+=4
                elif d==ord('f'):
                    if i+2>=n or p[i+2]!=ord('['): raise PatternError("missing '[' after '%f' in pattern")
                    st, ni = self.parse_set(i+2)
                    item=('frontier',st); i=ni
                elif 49<=d<=57:
                    item=('backref',d-48); i+=2
                elif chr(d).isalnum() and pat_class_match(97,d) is not None and chr(d).lower() in 'acdg lpsuwx':
                    # class; need ensure letter in list
                    if chr(d).lower() not in 'acdglpsuwx': 
                        # unknown alnum after % is literal? Lua treats as ??? use literal if not class? Actually classes include z maybe
                        item=('char',('lit',d)); i+=2
                    else:
                        item=('char',('class',d)); i+=2
                elif chr(d).isalnum() and chr(d).lower()=='z':
                    item=('char',('class',d)); i+=2
                else:
                    item=('char',('lit',d)); i+=2
            elif c==ord('['):
                st,ni=self.parse_set(i); item=('char',('set',st)); i=ni
            elif c==ord('.'):
                item=('char',('any',)); i+=1
            else:
                item=('char',('lit',c)); i+=1
            # quantifier
            q=None
            if i<n and p[i] in b'*+-?':
                q=chr(p[i]); i+=1
            if item[0] in ('bal','frontier','backref') :
                toks.append(item)
                if q: 
                    # Lua doesn't allow suffix for these; treat quantifier as literal? Instead append as char item
                    toks.append(('char',('lit',ord(q))))
            else:
                toks.append((item[0],item[1],q))
        self.tokens=toks
    def parse_set(self,i):
        p=self.pat; n=len(p); i+=1; neg=False
        if i<n and p[i]==ord('^'): neg=True; i+=1
        elems=[]
        first=True
        while True:
            if i>=n: raise PatternError("malformed pattern (missing ']')")
            c=p[i]
            if c==ord(']') and not first:
                i+=1; break
            first=False
            if c==ord('%'):
                if i+1>=n: raise PatternError("malformed pattern (ends with '%')")
                d=p[i+1]
                if chr(d).lower() in 'acdglpsuwxz' and chr(d).isalpha():
                    elems.append(('class',d)); i+=2; continue
                else:
                    lo=d; i+=2
            else:
                lo=c; i+=1
            if i+1<n and p[i]==ord('-') and p[i+1]!=ord(']'):
                hi=p[i+1]; 
                # hi could be escaped? Lua doesn't treat % as range endpoint specially often
                elems.append(('range',lo,hi)); i+=2
            else:
                elems.append(('char',lo))
        return (neg,elems), i

def single_match(spec,c):
    kind=spec[0]
    if kind=='lit': return c==spec[1]
    if kind=='any': return True
    if kind=='class':
        r=pat_class_match(c,spec[1]); return bool(r)
    if kind=='set':
        neg,elems=spec[1]; res=False
        for e in elems:
            if e[0]=='char' and c==e[1]: res=True; break
            if e[0]=='range' and e[1]<=c<=e[2]: res=True; break
            if e[0]=='class' and pat_class_match(c,e[1]): res=True; break
        return (not res) if neg else res
    return False

class Matcher:
    def __init__(self, subj, pattern):
        self.s=subj; self.p=pattern; self.ncaps=pattern.ncaps
    def match_from(self, start):
        caps=[None]*self.ncaps
        res=self.rec(start,0,caps)
        if res is None: return None
        return (res, caps)
    def rec(self, pos, ti, caps):
        toks=self.p.tokens
        if ti>=len(toks):
            return pos
        tok=toks[ti]
        kind=tok[0]
        if kind=='open':
            idx=tok[1]; old=caps[idx]; caps[idx]=('start',pos)
            r=self.rec(pos,ti+1,caps)
            if r is None: caps[idx]=old
            return r
        if kind=='poscap':
            idx=tok[1]; old=caps[idx]; caps[idx]=('pos',pos+1)
            r=self.rec(pos,ti+1,caps)
            if r is None: caps[idx]=old
            return r
        if kind=='close':
            # find an open capture
            idx=None
            for i in range(self.ncaps-1,-1,-1):
                if caps[i] is not None and caps[i][0]=='start': idx=i; break
            if idx is None: raise PatternError("invalid pattern capture")
            old=caps[idx]; caps[idx]=('str', caps[idx][1], pos)
            r=self.rec(pos,ti+1,caps)
            if r is None: caps[idx]=old
            return r
        if kind=='end':
            return pos if pos==len(self.s) else None
        if kind=='bal':
            x,y=tok[1],tok[2]
            if pos>=len(self.s) or self.s[pos]!=x: return None
            depth=1; i=pos+1
            while i<len(self.s):
                if self.s[i]==y:
                    depth-=1
                    if depth==0: return self.rec(i+1,ti+1,caps)
                elif self.s[i]==x: depth+=1
                i+=1
            return None
        if kind=='frontier':
            spec=tok[1]
            prev= self.s[pos-1] if pos>0 else 0
            cur= self.s[pos] if pos<len(self.s) else 0
            # frontier: prev not in set, cur in set (using set matcher with pseudo char function)
            def in_set(ch):
                # build spec as ('set',...)
                return single_match(('set',spec), ch)
            if not in_set(prev) and in_set(cur): return self.rec(pos,ti+1,caps)
            return None
        if kind=='backref':
            nref=tok[1]
            if nref<1 or nref>self.ncaps: raise PatternError("invalid capture index %%%d" % nref)
            cap=caps[nref-1]
            if cap is None or cap[0]!='str': raise PatternError("unfinished capture" if cap and cap[0]=='start' else "invalid capture index %%%d" % nref)
            data=self.s[cap[1]:cap[2]]
            if self.s[pos:pos+len(data)]==data: return self.rec(pos+len(data),ti+1,caps)
            return None
        if kind=='char':
            spec=tok[1]; q=tok[2]
            if q is None:
                if pos<len(self.s) and single_match(spec,self.s[pos]): return self.rec(pos+1,ti+1,caps)
                return None
            # count max
            cnt=0
            while pos+cnt<len(self.s) and single_match(spec,self.s[pos+cnt]): cnt+=1
            if q=='*':
                for k in range(cnt,-1,-1):
                    r=self.rec(pos+k,ti+1,caps)
                    if r is not None: return r
                return None
            if q=='+':
                for k in range(cnt,0,-1):
                    r=self.rec(pos+k,ti+1,caps)
                    if r is not None: return r
                return None
            if q=='-':
                for k in range(0,cnt+1):
                    r=self.rec(pos+k,ti+1,caps)
                    if r is not None: return r
                return None
            if q=='?':
                if cnt>0:
                    r=self.rec(pos+1,ti+1,caps)
                    if r is not None: return r
                return self.rec(pos,ti+1,caps)
        return None
    def get_captures(self,caps,whole_start,whole_end):
        if self.ncaps==0: return [self.s[whole_start:whole_end]]
        out=[]
        for cap in caps:
            if cap is None: out.append(None)
            elif cap[0]=='pos': out.append(cap[1])
            elif cap[0]=='str': out.append(self.s[cap[1]:cap[2]])
            else: out.append(None)
        return out

def pat_find_from(vm, subj, pat, start0):
    # start0 0-based
    m=Matcher(subj, pat)
    if pat.anchored:
        r=m.match_from(start0)
        if r: return (start0,r[0],r[1])
        return None
    for s in range(start0, len(subj)+1):
        r=m.match_from(s)
        if r: return (s,r[0],r[1])
    return None

