def vm_tostring(vm,v):
    if isinstance(v,(LuaTable,UserData,LuaFunction,BuiltinFunction,LuaThread)) or True:
        mm=vm.get_metamethod(v,b'__tostring')
        if mm is not None:
            r=vm.call_value(mm,[v],'metamethod',b'tostring')
