            out.append(37); i+=2; continue
        j=i+1; flags=b''
        while j<n and fmt[j] in b'-+ #0': flags+=bytes([fmt[j]]); j+=1
        width=None
        if j<n and fmt[j]==42:
            width=arg_integer(vm,args,argidx,fname); argidx+=1; j+=1
        else:
