                while j<n and 48<=fmt[j]<=57: w+=bytes([fmt[j]]); j+=1
                prec=int(w) if w else 0
        # length modifiers ignored (h,l,ll etc) like lua? Lua allows? skip letters
        while j<n and fmt[j] in b'hlL': j+=1
        if j>=n: vm.arg_error(1,fname,b"invalid option '%%' to 'format'")
        conv=chr(fmt[j]); j+=1
        cur_argidx=argidx
        if conv in 'di':
            v=arg_number(vm,args,argidx,fname); argidx+=1
            if is_float(v) and not (v==int(v) and INT_MIN<=v<=INT_MAX): vm.arg_error(cur_argidx,fname,b"number has no integer representation")
            iv=int(v); spec='{:'+ ('<' if b'-' in flags else ('>' if True else '')) + '}'
