            s=format_float_c(fv,conv,flags,width,prec); out.extend(s.encode())
        elif conv=='a' or conv=='A':
            v=arg_number(vm,args,argidx,fname); argidx+=1; fv=float(v); s=format_float_a(fv, conv=='A',flags,width,prec); out.extend(s.encode())
        elif conv=='c':
