def apply_pad_bytes(s, flags,width, zero_ok):
    if width is None or len(s)>=width: return s
    padlen=width-len(s)
    if b'-' in flags: return s+b' '*padlen
    if b'0' in flags and zero_ok: return b'0'*padlen+s
    return b' '*padlen+s

def format_int_c(iv,conv,flags,width,prec,signed=True):
    neg=False
    if conv=='d':
        if iv<0: neg=True; digits=str(-iv)
        else: digits=str(iv)
    elif conv=='u': digits=str(iv)
    elif conv=='o': digits=format(iv,'o')
    elif conv=='x': digits=format(iv,'x')
    elif conv=='X': digits=format(iv,'X')
    else: digits=str(iv)
    prefix=''
    if signed:
        if neg: prefix='-'
        elif b'+' in flags: prefix='+'
        elif b' ' in flags: prefix=' '
    if b'#' in flags:
        if conv=='o' and not digits.startswith('0'): prefix+='0'
        if conv=='x': prefix+='0x'
        if conv=='X': prefix+='0X'
    if prec is not None:
        if prec==0 and ((conv=='d' and iv==0) or (iv==0 and conv!='d')):
            digits=''
        else:
            digits=digits.rjust(prec,'0')
    s=prefix+digits
    if width is not None and len(s)<width:
        if b'-' in flags: s=s+' '*(width-len(s))
        elif b'0' in flags and prec is None: 
            # zero pad after prefix
            s=prefix+'0'*(width-len(s))+digits
        else: s=' '*(width-len(s))+s
    return s

def format_float_c(fv,conv,flags,width,prec):
    if math.isnan(fv): body='nan'
    elif math.isinf(fv): body='inf' if fv>0 else '-inf'
    else:
        p=6 if prec is None else prec
        # python's format aligns to C for most cases
        body=format(fv, '.%d%s' % (p, conv))
        # C nan sign? body from python may be 'nan'
    # sign flags
    if not body.startswith('-'):
        if b'+' in flags: body='+'+body
        elif b' ' in flags: body=' '+body
    if b'#' in flags and '.' not in body and conv not in 'aA':
        # ensure decimal point for e/E/f/g
        if 'e' in body or 'E' in body:
            idx=body.find('e') if 'e' in body else body.find('E')
            body=body[:idx]+'.'+body[idx:]
        elif 'inf' not in body and 'nan' not in body:
            body+='.'
    if width is not None and len(body)<width:
        if b'-' in flags: body=body+' '*(width-len(body))
        elif b'0' in flags and 'inf' not in body and 'nan' not in body:
            if body[0] in '+- ': body=body[0]+'0'*(width-len(body))+body[1:]
            else: body='0'*(width-len(body))+body
        else: body=' '*(width-len(body))+body
    return body

def format_float_a(fv, upper, flags, width, prec):
    if math.isnan(fv): s='nan'
    elif math.isinf(fv): s='inf' if fv>0 else '-inf'
    elif fv==0.0: s='-0x0p+0' if math.copysign(1,fv)<0 else '0x0p+0'
    else:
        h=float.hex(fv)  # e.g. 0x1.8000000000000p+00
        # strip trailing zeros in fraction
        mant,exp=h.split('p'); exp=int(exp)
        if '.' in mant:
            mant=mant.rstrip('0').rstrip('.')
        s=f"{mant}p{exp:+d}"
        if prec is not None:
            # C %a with precision rounds mantissa fraction digits; approximate using float.hex? skip rare
            pass
    if upper: s=s.upper().replace('P','P')
    if not s.startswith('-'):
        if b'+' in flags: s='+'+s
        elif b' ' in flags: s=' '+s
    if width is not None and len(s)<width:
        if b'-' in flags: s=s+' '*(width-len(s))
        elif b'0' in flags: s='0'*(width-len(s))+s if not s.startswith(('+','-',' ')) else s[0]+'0'*(width-len(s))+s[1:]
        else: s=' '*(width-len(s))+s
    return s

def format_q(vm,v):
    if v is None: return b'nil'
    if isinstance(v,bool): return b'true' if v else b'false'
    if is_int(v): return str(v).encode()
    if is_float(v):
        if math.isnan(v): return b'(0/0)'
        if math.isinf(v): return b'(1/0)' if v>0 else b'(-1/0)'
        return lua_num2str(v).encode()
    if isinstance(v,bytes):
        out=bytearray(b'"')
        for ch in v:
            if ch==34: out+=b'\\"'
            elif ch==92: out+=b'\\\\'
            elif ch==10: out+=b'\\\n'
            elif ch==13: out+=b'\\r'
            elif 32<=ch<127: out.append(ch)
            else: out+=('\\%03d'%ch).encode()
        out.append(34); return bytes(out)
    # Lua %q for other types errors
    vm.arg_error(2,'string.format',b"specifier '%q' cannot have argument of type %s"%typename(v).encode()) if False else vm.rt_error(b"bad argument to 'format' (specifier '%q')")
    return b''

