        if fmt[i]!=37: # %
            out.append(fmt[i]); i+=1; continue
        if i+1<n and fmt[i+1]==37:
            out.append(37); i+=2; continue
        j=i+1; flags=b''
        while j<n and fmt[j] in b'-+ #0': flags+=bytes([fmt[j]]); j+=1
        width=None
        if j<n and fmt[j]==42:
            width=arg_integer(vm,args,argidx,fname); argidx+=1; j+=1
        else:
            w=b''
            while j<n and 48<=fmt[j]<=57: w+=bytes([fmt[j]]); j+=1
            if w: width=int(w)
        prec=None
        if j<n and fmt[j]==46:
            j+=1
            if j<n and fmt[j]==42:
                prec=arg_integer(vm,args,argidx,fname); argidx+=1; j+=1
            else:
                w=b''
                while j<n and 48<=fmt[j]<=57: w+=bytes([fmt[j]]); j+=1
                prec=int(w) if w else 0
        # length modifiers ignored (h,l,ll etc) like lua? Lua allows? skip letters
        while j<n and fmt[j] in b'hlL': j+=1
        if j>=n: vm.arg_error(1,fname,b"invalid option '%%' to 'format'")
        conv=chr(fmt[j]); j+=1
        cur_argidx=argidx
        if conv in 'di':
            v=arg_number(vm,args,argidx,fname); argidx+=1
            if is_float(v) and not (v==int(v) and INT_MIN<=v<=INT_MAX): vm.arg_error(cur_argidx,fname,b"number has no integer representation")
            iv=int(v); spec='{:'+ ('<' if b'-' in flags else ('>' if True else '')) + '}'
            # use python format via C-like manual
            s=format_int_c(iv,'d',flags,width,prec)
            out.extend(s.encode())
        elif conv in 'ouxX':
            v=arg_number(vm,args,argidx,fname); argidx+=1
            if is_float(v) and not (v==int(v) and INT_MIN<=v<=INT_MAX): vm.arg_error(cur_argidx,fname,b"number has no integer representation")
            iv=int(v) & MASK64; s=format_int_c(iv,conv,flags,width,prec,signed=False); out.extend(s.encode())
