def apply_pad_bytes(s, flags,width, zero_ok):
    if width is None or len(s)>=width: return s
    padlen=width-len(s)
    if b'-' in flags: return s+b' '*padlen
    if b'0' in flags and zero_ok: return b'0'*padlen+s
    return b' '*padlen+s

def format_int_c(iv,conv,flags,width,prec,signed=True):
    neg=False
    if conv=='d':
        if iv<0: neg=True; digits=str(-iv)
        else: digits=str(iv)
    elif conv=='u': digits=str(iv)
    elif conv=='o': digits=format(iv,'o')
    elif conv=='x': digits=format(iv,'x')
    elif conv=='X': digits=format(iv,'X')
    else: digits=str(iv)
    prefix=''
    if signed:
        if neg: prefix='-'
        elif b'+' in flags: prefix='+'
        elif b' ' in flags: prefix=' '
    if b'#' in flags:
        if conv=='o' and not digits.startswith('0'): prefix+='0'
        if conv=='x': prefix+='0x'
        if conv=='X': prefix+='0X'
    if prec is not None:
        if prec==0 and ((conv=='d' and iv==0) or (iv==0 and conv!='d')):
            digits=''
        else:
            digits=digits.rjust(prec,'0')
    s=prefix+digits
