def vm_resume(vm,co,args):
    if co.status=='dead': return [False,b"cannot resume dead coroutine"]
    if co.status in ('running','normal'): return [False,b"cannot resume non-suspended coroutine"]
    caller=vm.current_thread
    if caller is not None: caller.status='normal'
    co.status='running'
    ev_run,ev_done=_thread_events[id(co)]
    co.exchange=('resume',args)
    if not co.started:
        co.started=True
        th=threading.Thread(target=coroutine_thread_main,args=(vm,co),daemon=True); co.thread=th; th.start()
    else:
        ev_run.set()
    ev_done.wait(); ev_done.clear()
    kind,data=co.exchange
    if caller is not None and caller.status=='normal': caller.status='running'
    if kind=='yield': co.status='suspended'; return [True]+list(data)
    if kind=='return': co.status='dead'; return [True]+list(data)
    if kind=='error': co.status='dead'; return [False, data.value if isinstance(data,LuaError) else data]
    if kind=='closed': co.status='dead'; return [True]
    return [True]
def coroutine_thread_main(vm,co):
    ev_run,ev_done=_thread_events[id(co)]
    ev_run.wait(); ev_run.clear()
    vm.current_thread=co
    kind,args=co.exchange
    try:
        res=vm.call_value(co.func,args)
        co.exchange=('return',res)
    except LuaError as e:
        co.last_error_exc=e if hasattr(co,'last_error_exc') else None
        try: co.last_error_exc=e
        except Exception: pass
        co.exchange=('error',e)
    except CloseSignal:
        co.exchange=('closed',None)
    except RecursionError:
        co.exchange=('error',LuaError(b"stack overflow"))
    co.status='dead'
    ev_done.set()
