    if co.status=='dead': return [True]
    if co.status=='running': return [False,b"cannot close a running coroutine"]
    if co.status=='normal': return [False,b"cannot close a normal coroutine"]
    # suspended
    if not co.started: co.status='dead'; return [True]
    ev_run,ev_done=_thread_events[id(co)]
    co.exchange=('close',None); ev_run.set(); ev_done.wait(); ev_done.clear()
    co.status='dead'; return [True]

